			out += line(cx + rIn * Math.cos(a), cy + rIn * Math.sin(a), cx + rOut * Math.cos(a), cy + rOut * Math.sin(a), stroke, width);
		}
		return out;
	}

	/* Zigzag boundary between a hoist band and the field (Gulf flags): `teeth`
	   white points biting into the coloured field. */
	function serrated(bandWidth, teeth, bandColor, fieldColor) {
		const step = H / teeth;
		const points = [[0, 0]];
		for (let i = 0; i < teeth; i++) {
			points.push([bandWidth + step * 0.6, i * step + step * 0.5]);
			points.push([bandWidth, (i + 1) * step]);
		}
		points.push([0, H]);
		return rect(0, 0, W, H, fieldColor) + poly(points, bandColor);
	}

	/* ── flag bodies ──────────────────────────────────────────────────────
	   One entry per ISO-3166 alpha-2 code, each returning the *inside* of the
