	   once by `svg()`. */
	const BODY = {
		/* ── Europe ─────────────────────────────────────────────────────── */
		DE: () => hBands(["#000000", "#DD0000", "#FFCE00"]),
		NL: () => hBands(["#AE1C28", "#FFFFFF", "#21468B"]),
