		CZ: () => hBands(["#FFFFFF", "#D7141A"]) + poly([[0, 0], [15, 10], [0, H]], "#11457E"),
		SK: () =>
			hBands(["#FFFFFF", "#0B4EA2", "#EE1C25"]) +
			poly([[4.6, 6.4], [10.4, 6.4], [10.4, 11.8], [7.5, 14.4], [4.6, 11.8]], "#FFFFFF") +
