		MK: () => rect(0, 0, W, H, "#D20000") + rays(15, 10, 3, 24, 8, "#FFE400", 1.9) + circ(15, 10, 3, "#FFE400"),
		GE: () => {
			const small = (cx, cy) => rect(cx - 0.45, cy - 1.7, 0.9, 3.4, "#DA291C") + rect(cx - 1.7, cy - 0.45, 3.4, 0.9, "#DA291C");
			return (
				rect(0, 0, W, H, "#FFFFFF") +
				rect(12.5, 0, 5, H, "#DA291C") +
				rect(0, 7.5, W, 5, "#DA291C") +
				small(6.25, 3.75) + small(23.75, 3.75) + small(6.25, 16.25) + small(23.75, 16.25)
			);
		},
		AM: () => hBands(["#D90012", "#0033A0", "#F2A800"]),
		XK: null,

		/* ── Americas ───────────────────────────────────────────────────── */
		US: () => {
			const stripe = H / 13;
			let out = "";
			for (let i = 0; i < 13; i++) out += rect(0, i * stripe, W, stripe, i % 2 === 0 ? "#B22234" : "#FFFFFF");
			const cw = 12;
			const ch = 7 * stripe;
			out += rect(0, 0, cw, ch, "#3C3B6E");
			for (let row = 0; row < 9; row++) {
				const odd = row % 2 === 1;
				const cols = odd ? 5 : 6;
				for (let col = 0; col < cols; col++) {
					const x = odd ? ((col + 1) / 6) * cw : ((col + 0.5) / 6) * cw;
					out += circ(x, ((row + 0.5) / 9) * ch, 0.45, "#FFFFFF");
				}
			}
			return out;
		},
		CA: () => {
			/* Maple leaf as a union of overlapping lobes: a single traced
			   outline would cost a 600-character path, and a star-shaped
			   polygon reads wrong — lobes in one colour read as one leaf. */
			const centre = [[15, 3.2], [17.4, 7.6], [17, 11.6], [15, 12.8], [13, 11.6], [12.6, 7.6]];
			const wing = [[15, 6.4], [19.4, 5.2], [18.6, 8.2], [22.6, 7.8], [20.6, 10.4], [23.2, 12.4], [18.2, 13], [15, 11.8]];
			const lobe = [[15, 10.6], [19.8, 14.8], [15.2, 14.9]];
			const mirror = (shape) => shape.map(([x, y]) => [30 - x, y]).reverse();
			return (
				vBands(["#FF0000", "#FFFFFF", "#FF0000"], [1, 2, 1]) +
				poly(centre, "#FF0000") +
				poly(wing, "#FF0000") + poly(mirror(wing), "#FF0000") +
				poly(lobe, "#FF0000") + poly(mirror(lobe), "#FF0000") +
				rect(14.5, 13.2, 1, 3.8, "#FF0000")
			);
		},
		MX: () =>
			vBands(["#006847", "#FFFFFF", "#CE1126"]) +
			circ(15, 9.4, 1.5, "#6B8E23") +
			poly([[13.4, 11.2], [16.6, 11.2], [15, 9]], "#8B5A2B"),
		GT: () => vBands(["#4997D0", "#FFFFFF", "#4997D0"]) + circ(15, 10, 1.7, "#B08D57"),
		BR: () =>
			rect(0, 0, W, H, "#009B3A") +
			poly([[15, 2], [28, 10], [15, 18], [2, 10]], "#FEDF00") +
			circ(15, 10, 3.6, "#002776") +
			path("M11.9 8.5 Q15 11.3 18.1 8.8", "none", ' stroke="#FFFFFF" stroke-width="0.8"'),
		AR: () => hBands(["#74ACDF", "#FFFFFF", "#74ACDF"]) + rays(15, 10, 1.8, 3.6, 16, "#F6B40E", 0.4) + circ(15, 10, 1.8, "#F6B40E"),
		UY: () => {
			const band = H / 9;
			const canton = 5 * band;
			let out = hBands(["#FFFFFF", "#0038A8", "#FFFFFF", "#0038A8", "#FFFFFF", "#0038A8", "#FFFFFF", "#0038A8", "#FFFFFF"]);
			out += rect(0, 0, canton, canton, "#FFFFFF");
			out += rays(canton / 2, canton / 2, 1.3, 2.7, 16, "#FCD116", 0.5);
			return out + circ(canton / 2, canton / 2, 1.3, "#FCD116");
		},
		PE: () => vBands(["#D91023", "#FFFFFF", "#D91023"]),
		CO: () => hBands(["#FCD116", "#003893", "#CE1126"], [2, 1, 1]),
		EC: () => hBands(["#FFDD00", "#034EA2", "#ED1C24"], [2, 1, 1]) + circ(15, 10, 1.8, "#8A5A2B") + circ(15, 9.2, 0.9, "#FCD116"),
		VE: () => {
			let out = hBands(["#FFCC00", "#00247D", "#CF142B"]);
			for (let i = 0; i < 8; i++) {
				const a = ((-122 + i * (64 / 7)) * Math.PI) / 180;
				out += star(15 + 7.4 * Math.cos(a), 17.5 + 7.4 * Math.sin(a), 0.75, "#FFFFFF");
			}
			return out;
		},
		CL: () => hBands(["#FFFFFF", "#D52B1E"]) + rect(0, 0, 10, 10, "#0039A6") + star(5, 5, 2.6, "#FFFFFF"),

		/* ── Middle East, Caucasus, Central Asia ────────────────────────── */
		TR: () => rect(0, 0, W, H, "#E30A17") + crescent(12, 10, 4.6, 3.7, 1.5, 0, "#FFFFFF", "#E30A17") + star(19.4, 10, 1.8, "#FFFFFF"),
		AZ: () =>
			hBands(["#00B5E2", "#EF3340", "#509E2F"]) +
			crescent(14.2, 10, 2.7, 2.2, 0.9, 0, "#FFFFFF", "#EF3340") +
			star(17.8, 10, 1.2, "#FFFFFF", -90, 8, 0.55),
		KZ: () =>
			rect(0, 0, W, H, "#00AFCA") +
			rect(1.6, 1, 1.2, H - 2, "#FEC50C") +
			rays(16.4, 10, 3.2, 5.6, 32, "#FEC50C", 0.45) +
			circ(16.4, 10, 3.2, "#FEC50C"),
		SA: () =>
			rect(0, 0, W, H, "#006C35") +
			rect(8, 12.8, 14, 0.9, "#FFFFFF") +
			path("M9 9.8 q1.7 -2.4 3.4 0 t3.4 0 t3.4 0 t3.4 0", "none", ' stroke="#FFFFFF" stroke-width="0.95"'),
		QA: () => serrated(10.5, 9, "#FFFFFF", "#8A1538"),
		BH: () => serrated(9, 5, "#FFFFFF", "#CE1126"),
		KW: () => hBands(["#007A3D", "#FFFFFF", "#CE1126"]) + poly([[0, 0], [7.5, 5], [7.5, 15], [0, H]], "#000000"),
		OM: () =>
			rect(0, 0, 8, H, "#CE1126") +
			rect(8, 0, W - 8, H / 3, "#FFFFFF") +
			rect(8, H / 3, W - 8, H / 3, "#CE1126") +
			rect(8, (2 * H) / 3, W - 8, H / 3, "#007A3D"),
		JO: () => hBands(["#000000", "#FFFFFF", "#007A3D"]) + poly([[0, 0], [15, 10], [0, H]], "#CE1126") + star(5, 10, 1.3, "#FFFFFF"),
		LB: () =>
			hBands(["#ED1C24", "#FFFFFF", "#ED1C24"]) +
			poly([[15, 5.2], [17.8, 9], [12.2, 9]], "#00A651") +
			poly([[15, 7.2], [19.4, 12.4], [10.6, 12.4]], "#00A651") +
			rect(14.5, 12.2, 1, 2, "#6B4A2B"),
		IQ: () =>
			hBands(["#CE1126", "#FFFFFF", "#000000"]) +
			path("M10 11 q1 -2.4 2 -2.4 t2 2.4", "none", ' stroke="#007A3D" stroke-width="0.8"') +
			path("M16 11 q1 -2.4 2 -2.4 t2 2.4", "none", ' stroke="#007A3D" stroke-width="0.8"'),
		SY: () => hBands(["#CE1126", "#FFFFFF", "#000000"]) + star(11, 10, 1.7, "#007A3D") + star(19, 10, 1.7, "#007A3D"),
		EG: () =>
			hBands(["#CE1126", "#FFFFFF", "#000000"]) +
			poly([[13.4, 8.2], [16.6, 8.2], [15.9, 11.6], [14.1, 11.6]], "#C09300") +
			circ(15, 7.9, 0.9, "#C09300"),
		AE: () =>
			rect(0, 0, 7.5, H, "#FF0000") +
			rect(7.5, 0, W - 7.5, H / 3, "#00732F") +
			rect(7.5, H / 3, W - 7.5, H / 3, "#FFFFFF") +
			rect(7.5, (2 * H) / 3, W - 7.5, H / 3, "#000000"),
		IR: () =>
			hBands(["#239F40", "#FFFFFF", "#DA0000"]) +
			poly([[15, 7.8], [16.3, 9.6], [15, 12.2], [13.7, 9.6]], "#DA0000") +
			rect(14.6, 8.4, 0.8, 3.4, "#DA0000"),
		IL: () =>
			rect(0, 0, W, H, "#FFFFFF") +
			rect(0, 2.6, W, 2.4, "#0038B8") +
			rect(0, 15, W, 2.4, "#0038B8") +
			polyline([[15, 6.4], [18.1, 11.8], [11.9, 11.8], [15, 6.4]], ' fill="none" stroke="#0038B8" stroke-width="0.75"') +
			polyline([[15, 13.6], [11.9, 8.2], [18.1, 8.2], [15, 13.6]], ' fill="none" stroke="#0038B8" stroke-width="0.75"'),

		/* ── Africa ─────────────────────────────────────────────────────── */
		MA: () => {
			const list = [];
			for (let i = 0; i < 5; i++) {
				const a = ((-90 + i * 144) * Math.PI) / 180;
				list.push([15 + 4.6 * Math.cos(a), 10 + 4.6 * Math.sin(a)]);
			}
			return rect(0, 0, W, H, "#C1272D") + polyline(list, ' fill="none" stroke="#006233" stroke-width="1.2"');
		},
		ZA: () =>
			rect(0, 0, W, 10, "#E03C31") +
			rect(0, 10, W, 10, "#001489") +
			path("M0 0 L15 10 L30 10 M0 20 L15 10", "none", ' stroke="#FFFFFF" stroke-width="6.7"') +
			path("M0 0 L15 10 L30 10 M0 20 L15 10", "none", ' stroke="#007749" stroke-width="4"') +
			poly([[0, 1], [0, 19], [9, 10]], "#FFB81C") +
			poly([[0, 3.2], [0, 16.8], [6.6, 10]], "#000000"),
		NG: () => vBands(["#008753", "#FFFFFF", "#008753"]),
		KE: () =>
			hBands(["#000000", "#FFFFFF", "#BB0000", "#FFFFFF", "#006600"], [4, 1, 4, 1, 4]) +
			poly([[15, 3.8], [17.8, 10], [15, 16.2], [12.2, 10]], "#FFFFFF") +
			poly([[15, 5.2], [16.7, 10], [15, 14.8], [13.3, 10]], "#BB0000") +
			line(11.4, 5.4, 18.6, 14.6, "#000000", 0.5) +
			line(18.6, 5.4, 11.4, 14.6, "#000000", 0.5),
		CI: () => vBands(["#F77F00", "#FFFFFF", "#009E60"]),
		BI: () =>
			rect(0, 0, W, H, "#CE1126") +
			poly([[0, 0], [0, H], [15, 10]], "#1EB53A") +
			poly([[W, 0], [W, H], [15, 10]], "#1EB53A") +
			line(0, 0, W, H, "#FFFFFF", 4) +
			line(0, H, W, 0, "#FFFFFF", 4) +
			circ(15, 10, 4.2, "#FFFFFF") +
			star(15, 7.7, 1.1, "#CE1126") +
			star(13.2, 11.2, 1.1, "#CE1126") +
			star(16.8, 11.2, 1.1, "#CE1126"),
		MU: () => hBands(["#EA2839", "#1A206D", "#FFD500", "#00A551"]),

		/* ── Asia and the Pacific ───────────────────────────────────────── */
		IN: () =>
			hBands(["#FF9933", "#FFFFFF", "#138808"]) +
			rays(15, 10, 0.5, 2, 24, "#000080", 0.2) +
			circ(15, 10, 2, "none", ' stroke="#000080" stroke-width="0.35"') +
			circ(15, 10, 0.4, "#000080"),
		PK: () =>
			rect(0, 0, 7.5, H, "#FFFFFF") +
			rect(7.5, 0, W - 7.5, H, "#01411C") +
			crescent(17.4, 10, 4, 3.3, 1.3, -0.6, "#FFFFFF", "#01411C") +
			star(22.6, 7.2, 1.3, "#FFFFFF"),
		BD: () => rect(0, 0, W, H, "#006A4E") + circ(13.6, 10, 5.4, "#F42A41"),
		CN: () =>
			rect(0, 0, W, H, "#EE1C25") +
			star(5.6, 5.2, 3, "#FFDE00") +
			star(11, 2.2, 1, "#FFDE00", -70) +
			star(13.2, 4.6, 1, "#FFDE00", -50) +
			star(13.2, 7.8, 1, "#FFDE00", -30) +
			star(11, 10.2, 1, "#FFDE00", -10),
		JP: () => rect(0, 0, W, H, "#FFFFFF") + circ(15, 10, 6, "#BC002D"),
		KR: () => {
			/* Taegeuk: two half discs plus two small discs give the S-curve,
			   then the four trigrams at the corners. */
			let out = rect(0, 0, W, H, "#FFFFFF");
			out += path("M10.5 10 A4.5 4.5 0 0 1 19.5 10 Z", "#CD2E3A");
			out += path("M10.5 10 A4.5 4.5 0 0 0 19.5 10 Z", "#0047A0");
			out += circ(12.75, 10, 2.25, "#CD2E3A") + circ(17.25, 10, 2.25, "#0047A0");
			const trigram = (cx, cy, rot, broken) => {
				let g = "";
				for (let i = 0; i < 3; i++) {
					const y = cy - 1.6 + i * 1.6;
					g += broken && i === 1
						? rect(cx - 2.4, y - 0.35, 2, 0.7, "#000000") + rect(cx + 0.4, y - 0.35, 2, 0.7, "#000000")
						: rect(cx - 2.4, y - 0.35, 4.8, 0.7, "#000000");
				}
				return `<g transform="rotate(${rot} ${cx} ${cy})">${g}</g>`;
			};
			return out + trigram(6.4, 5.2, 34, false) + trigram(6.4, 14.8, -34, true) + trigram(23.6, 5.2, -34, true) + trigram(23.6, 14.8, 34, false);
		},
		HK: () => {
			/* Bauhinia: five tangential petals swirling around a red centre. */
			let out = rect(0, 0, W, H, "#DE2910");
			for (let i = 0; i < 5; i++) {
				const a = ((-90 + i * 72) * Math.PI) / 180;
				const cx = 15 + 2.6 * Math.cos(a);
				const cy = 10 + 2.6 * Math.sin(a);
				out += `<ellipse cx="${r2(cx)}" cy="${r2(cy)}" rx="2.6" ry="1.5" fill="#FFFFFF" transform="rotate(${i * 72 + 74} ${r2(cx)} ${r2(cy)})"/>`;
			}
			return out + circ(15, 10, 0.8, "#DE2910");
