	function isRelayProxy(raw) {
		const value = String(raw || "").trim();
		if (!value || /^[a-z][a-z0-9+.-]*:\/\//i.test(value)) return false;
		return /^\[[^\]]+\](?::\d+)?$/.test(value) || /^(\d{1,3}\.){3}\d{1,3}(?::\d+)?$/.test(value);
	}

	/* Tooltip of the auto-replace switch. It says what the switch does on this
	   particular card: which slot can be replaced, that the replacement keeps
	   the country, and — for a bare-IP relay — that the new address becomes a
	   real exit rather than another relay. */
	function autoReplaceTip(entry) {
		if (!autoReplaceCountry(entry)) {
			return "تا وقتی کشور این اسلات معلوم نشده، کلید غیرفعال است.\nابتدا کشور را تشخیص دهید (آیکون 🌐 سربرگ کارت)؛\nبعد روشن و قابل استفاده می‌شود — برای هر نوع پروکسی.";
		}
		if (isRelayProxy(entry?.proxy)) {
			return "آدرس خام (رله) خروج نیست؛ اگر بمیرد یا دور بزند،\nجایش یک خروج واقعی همان کشور می‌آید.\nبررسی سلامت در پس‌زمینه و با cron پنل است.";
		}
		return "کلید باید روشن باشد تا این اسلات جایگزین شود.\nجایگزینی با گزینه‌ی تأییدشده (سالم) انجام می‌شود.\nهمان کشور و همان نوع اتصال حفظ می‌شود.";
	}

	function getLocState(root, index) {
		if (!root._locStates) root._locStates = [];
		return root._locStates[index] ||= {pool: [], protocol: "", loading: false, message: "", country: "", count: 10};
	}

	/* per-root test cache: index -> {ok, latency, ip, error, testing} */
	function getLocTestCache(root){
		if(!root._locTestCache) root._locTestCache = new Map();
		return root._locTestCache;
	}
	function setLocTestResult(root, idx, result){
		getLocTestCache(root).set(idx, result);
	}

	/* A result belongs to a slot identity + edit revision, not its current index. */
	function beginLocationTest(root, index) {
		const state = getLocState(root, index);
		const token = {state, revision: state.revision, proxy: readLocations(root)[index].proxy};
		state.testToken = token;
		setLocTestResult(root, index, {testing:true});
		return token;
	}
	function finishLocationTest(root, token, result) {
		const index = (root._locStates || []).indexOf(token.state);
		if (index < 0 || token.state.testToken !== token || token.state.revision !== token.revision || readLocations(root)[index]?.proxy !== token.proxy) return false;
		setLocTestResult(root, index, result);
		/* The test observed the real exit IP; its country is ground truth and
		   overrides whatever label the entry had (or fills a missing one). The
		   caller re-renders, so the card head picks the new flag up by itself. */
		if (result?.geo?.country) {
			const list = readLocations(root);
			if (list[index]) {
				list[index].country = String(result.geo.country).toUpperCase();
				list[index].country_name = result.geo.country_name || list[index].country_name || null;
				writeLocations(root, list, false);
			}
		}
		return true;
	}

	/* Debounced country detection for a manually entered address. The card head
	   is patched in place — a full re-render would steal the input's focus while
	   the admin is still typing. The server repeats the lookup at save time, so
	   an interrupted detection still ends up labelled. */
	function patchLocCountryHead(root, index) {
		const entry = readLocations(root)[index];
		const head = root.querySelector(`#user-locations .loc-card[data-idx="${index}"] .loc-country`);
		if (!entry || !head) return;
		head.innerHTML = `${flagMarkup(entry.country)}<span class="loc-name">${esc(locationDisplayName(entry))}</span>`;
	}

	/* The country is what makes the auto-replace switch usable, and detection is
	   asynchronous: without this the card kept the switch disabled until the
	   next full re-render. */
	function patchLocAutoReplace(root, index) {
		const entry = readLocations(root)[index];
		const card = root.querySelector(`#user-locations .loc-card[data-idx="${index}"]`);
		if (!entry || !card) return;
		const input = card.querySelector(".loc-auto-replace");
		if (input) {
			input.disabled = !String(entry.proxy || "").trim() || !autoReplaceCountry(entry);
			input.checked = entry.auto_replace === true;
		}
		const tip = card.querySelector(".loc-auto-tip");
		if (tip) tip.setAttribute("data-tip", autoReplaceTip(entry));
	}

	function scheduleGeoDetect(root, index, proxy) {
		root._geoTimers ||= new Map();
		const timers = root._geoTimers;
		clearTimeout(timers.get(index));
		if (!proxy) return;
		timers.set(index, setTimeout(async () => {
			timers.delete(index);
			try {
				const data = await api.post("/api/tools/geo-ip", { proxy });
				const list = readLocations(root);
				if (list[index]?.proxy !== proxy) return;
				if (!data?.country) {
					/* No provider answered: say so next to the input instead of
					   leaving a silent «بدون کشور» that looks like no feature. */
					if (!list[index].country) patchGeoStatus(root, index, "تشخیص خودکار جواب نداد — دکمه‌ی 🌐 سربرگ کارت را بزنید");
					return;
				}
				if (list[index].country) return;
				list[index].country = String(data.country).toUpperCase();
				list[index].country_name = data.country_name || null;
				writeLocations(root, list, false);
				patchLocCountryHead(root, index);
				patchLocAutoReplace(root, index);
			} catch {}
		}, 800));
	}

	/* On-demand country detection for one location — the same lookup the typing
	   path uses, but with a button and visible feedback: the flag appears on
	   success, a Persian error explains a total failure and points at the
	   manual picker. Runs the whole provider chain on the worker. */
	async function runGeoDetect(root, button) {
		const index = Number(button.dataset.idx);
		const list = readLocations(root);
		const proxy = String(list[index]?.proxy || "").trim();
		if (!proxy) return toast("ابتدا پروکسی این لوکیشن را وارد کنید.", "warn");
		if (button.disabled) return;
		button.disabled = true;
		patchGeoStatus(root, index, "در حال تشخیص کشور…");
		try {
			const data = await api.post("/api/tools/geo-ip", { proxy });
			if (data?.country) {
				const fresh = readLocations(root);
				if (fresh[index] && String(fresh[index].proxy || "").trim() === proxy) {
					fresh[index].country = String(data.country).toUpperCase();
					fresh[index].country_name = data.country_name || fresh[index].country_name || null;
					writeLocations(root, fresh, false);
					patchLocCountryHead(root, index);
					patchLocAutoReplace(root, index);
					patchGeoStatus(root, index, `✓ ${locationDisplayName(fresh[index])}${data.ip ? ` — ${data.ip}` : ""}`);
					toast(`لوکیشن ${fa(index + 1)}: ${locationDisplayName(fresh[index])}`, "ok");
				}
			} else {
				patchGeoStatus(root, index, "هیچ سرویس تشخیص کشور از سرور پنل پاسخ نداد — کشور را دستی انتخاب کنید");
				toast("تشخیص کشور ناموفق بود؛ فهرست دستی زیر همین دکمه است.", "warn");
			}
		} catch (error) {
			patchGeoStatus(root, index, `خطا: ${error.message || error}`);
		} finally {
			button.disabled = false;
		}
	}

	/* Fisher-Yates shuffle */
	function shuffleArray(arr){
		const a = [...arr];
		for(let i=a.length-1;i>0;i--){
			const j = Math.floor(Math.random() * (i+1));
			[a[i], a[j]] = [a[j], a[i]];
		}
		return a;
	}

	function latencyBadge(result){
		if(!result) return '';
		if(result.testing) return '<span class="ds-badge ds-tone-accent">⏳ تست...</span>';
		if(result.ok) {
			const ms = result.latency;
			const tone = ms > 700 ? "ds-tone-danger" : ms > 300 ? "ds-tone-warning" : "ds-tone-success";
			const note = result.test === "relay" ? " · رله" : result.test === "tcp" ? " · TCP" : "";
			return `<span class="ds-badge ${tone}">${ms}ms${note}</span>`;
		}
		/* A bare-IP ProxyIP that accepts TCP but relays nothing (or answers
		   without being a Cloudflare relay) is not a working exit — say so in
		   Persian instead of a cryptic English error. */
		if (result.protocol === "proxyip" && result.tcp_ok) {
			if (result.fail === "not-cf") return '<span class="ds-badge ds-tone-danger">✗ رله‌ی Cloudflare نیست</span>';
			return '<span class="ds-badge ds-tone-danger">✗ فقط TCP — رله نمی‌کند</span>';
		}
		return `<span class="ds-badge ds-tone-danger">✗ ${esc((result.error||'خطا').slice(0,30))}</span>`;
	}

	/* Card-head country label: Persian name first, then the English name that
	   came with the geo lookup, then the code — «بدون کشور» as the last resort. */
	function locationDisplayName(entry) {
		const code = String(entry?.country || "").toUpperCase();
		return COUNTRY_NAMES_FA[code] || entry?.country_name || entry?.country || "بدون کشور";
	}

	/* Inline status line under the manual proxy input — detection is async and
	   can fail silently (a Worker whose egress the geo services block); without
	   a visible state, «بدون کشور» reads exactly like a missing feature. */
	function patchGeoStatus(root, index, text) {
		const state = getLocState(root, index);
		state.geoStatus = text || "";
		const el = root.querySelector(`#user-locations .loc-geo-status[data-idx="${index}"]`);
		if (el) el.textContent = state.geoStatus;
	}

	/* One card per location — collapsed header + expandable body.
	   Each card is fully independent: manual paste or smart pick + per-card test. */
	function renderLocations(root) {
		const box = root.querySelector("#user-locations");
		if (!box) return;
		const active = typeof document !== "undefined" ? document.activeElement : null;
		const focus = active?.classList?.contains("loc-manual-input") && box.contains?.(active)
			? {state:getLocState(root,Number(active.dataset.idx)), value:active.value, start:active.selectionStart, end:active.selectionEnd} : null;
		const list = readLocations(root);
		const testCache = getLocTestCache(root);
		if (!list.length) {
			box.innerHTML = '<div class="loc-empty-state"><span class="loc-empty-icon">🌍</span><p>لوکیشنی ثبت نشده — کاربر مستقیم وصل می‌شود.</p><p class="dim">با «افزودن لوکیشن» یک اسلات خالی می‌سازید و پروکسی را در همان کارت وارد می‌کنید.</p></div>';
			return;
		}
		box.innerHTML = list
			.map((entry, index) => {
				const state = getLocState(root, index);
				const pool = state.pool;
				// build country options from pool if available
				let countryOptions = '<option value="">— انتخاب کشور —</option>';
				if(pool.length){
					const groups = new Map();
					for(const e of pool){
						const k = String(e.country||"").toUpperCase();
						if(!k) continue;
						if(!groups.has(k)) groups.set(k, []);
						groups.get(k).push(e);
					}
					const ordered = [...groups.entries()].sort((a,b)=>b[1].length - a[1].length);
					countryOptions = ordered.map(([code, entries])=> `<option value="${esc(code)}">${esc(countryLabel({country:code, country_name:entries[0].country_name}))} — ${entries.length}</option>`).join("") || countryOptions;
				}
				const isExpanded = root._expandedLoc === index;
				const result = testCache.get(index);
				const flag = flagMarkup(entry.country);
				const name = locationDisplayName(entry);
				const isEmpty = !String(entry.proxy || "").trim();
				return `
			<div class="loc-card${isExpanded ? " expanded" : ""}${isEmpty ? " is-empty" : ""}" data-idx="${index}">
				<div class="loc-card-head" data-toggle="${index}">
					<span class="loc-slot">${fa(index + 1)}</span>
					<span class="loc-id">
						<span class="loc-country">${flag}<span class="loc-name">${esc(name)}</span></span>
						<span class="loc-proxy-empty"${isEmpty ? "" : " hidden"}>خالی</span>
					</span>
					<span class="loc-ping-wrap">${isEmpty ? '<span class="ds-badge ds-tone-warning">خالی</span>' : latencyBadge(result)}</span>
					<span class="loc-actions">
						<button type="button" class="ds-btn is-sm is-ghost is-icon loc-geo-detect" data-idx="${index}" title="تشخیص کشور این پروکسی" aria-label="تشخیص کشور"${isEmpty ? " disabled" : ""}><svg class="ico" aria-hidden="true"><use href="#i-globe"/></svg></button>
						<button type="button" class="ds-btn is-sm is-ghost is-icon loc-test-single" data-idx="${index}" title="تست پینگ این لوکیشن" aria-label="تست پینگ"${result?.testing ? " disabled" : ""}><svg class="ico" aria-hidden="true"><use href="#i-zap"/></svg></button>
						<button type="button" class="ds-btn is-sm is-ghost is-icon loc-remove-btn" data-loc-remove="${index}" title="حذف این لوکیشن" aria-label="حذف"><svg class="ico" aria-hidden="true"><use href="#i-trash"/></svg></button>
						<button type="button" class="card-chev loc-toggle-btn" data-idx="${index}" aria-expanded="${isExpanded}" aria-label="${isExpanded ? "بستن لوکیشن" : "باز کردن لوکیشن"}"><svg class="ico" aria-hidden="true"><use href="#i-chevron-down"/></svg></button>
					</span>
				</div>
				<div class="loc-card-body"${isExpanded ? "" : " hidden"}>
					<div class="loc-block">
						<span class="loc-block-head">پروکسی دستی ${hintMarkup("IP خام = ProxyIP سازگار با BPB.\nترافیک Cloudflare از رله می‌گذرد؛ بقیه‌ی مقاصد مستقیم.\nبرای SOCKS یا HTTP پیشوند پروتکل را بنویسید:\nsocks5://host:1080 یا http://host:8080\nکشور به‌صورت خودکار تشخیص داده می‌شود؛\nاگر خودکار نشد، دکمه‌ی 🌐 سربرگ کارت.\n\nنکته‌ی https:// — پذیرفته می‌شود و مثل http:// با دستور CONNECT\nروی یک اتصال معمولی فرستاده می‌شود؛ یعنی به خودِ سرور پروکسی\nTLS برقرار نمی‌کنیم. اگر پروکسی‌تان فقط با TLS جواب می‌دهد،\nاز این نوع پشتیبانی نمی‌شود.")}</span>
						<div class="loc-input-row">
							<input type="text" dir="ltr" aria-label="پروکسی دستی" spellcheck="false" class="ds-input is-mono mono loc-manual-input" data-idx="${index}" value="${esc(entry.proxy)}" placeholder="88.198.149.98 یا socks5://host:1080">
						</div>
						<div class="loc-geo-status dim" data-idx="${index}" role="status">${esc(state.geoStatus || "")}</div>
					</div>
					<div class="loc-divider">یا</div>
					<div class="loc-block">
						<span class="loc-block-head">انتخاب هوشمند از فهرست رایگان ${hintMarkup("فهرست رایگان = پروکسی عمومی و ناشناس.\n«واکشی فهرست کشورها» استخر کاندیدها را پر می‌کند.\nتعداد = چند کاندید رندوم تست شود؛ بیشتر = دقیق‌تر.\n«بهترین از رندوم» سریع‌ترین کاندید سالم را می‌نشاند.")}</span>
						<div class="loc-input-row loc-fetch-row">
							<button type="button" class="ds-btn is-sm is-ghost loc-fetch-pool" data-idx="${index}"${state.loading ? " disabled" : ""}><svg class="ico" aria-hidden="true"><use href="#i-search"/></svg><span>واکشی فهرست کشورها</span></button>
							<span class="ds-select-wrap"><select class="ds-input ds-select loc-protocol" data-idx="${index}" aria-label="پروتکل فهرست"><option value="">همه پروتکل‌ها</option><option value="socks5">socks5</option><option value="socks4">socks4</option><option value="http">http</option></select><svg class="ds-select-caret" aria-hidden="true"><use href="#i-chevron-down"/></svg></span>
						<div class="ds-switch"><label class="ds-switch-control"><input type="checkbox" class="loc-auto-replace" data-idx="${index}" role="switch" aria-label="جایگزینی خودکار پروکسی خراب"${!isEmpty && autoReplaceCountry(entry) ? "" : " disabled"}${entry.auto_replace ? " checked" : ""}><span class="ds-switch-track" aria-hidden="true"></span></label><span class="ds-switch-text">جایگزینی خودکار پروکسی خراب ${hintMarkup(autoReplaceTip(entry), "loc-auto-tip")}</span></div>
						</div>
						<div class="loc-pool-status dim" role="status">${state.loading ? "در حال واکشی…" : esc(state.message)}</div>
						<div class="loc-input-row loc-pick-row">
							<span class="ds-select-wrap"><select class="ds-input ds-select loc-country-select" data-idx="${index}">${countryOptions}</select><svg class="ds-select-caret" aria-hidden="true"><use href="#i-chevron-down"/></svg></span>
							<label class="loc-count">تعداد <input type="number" class="ds-input loc-candidate-count" data-idx="${index}" value="${esc(state.count)}" min="3" max="20"></label>
							<button type="button" class="ds-btn is-sm is-primary loc-smart-pick" data-idx="${index}"${state.picking ? " disabled" : ""}>🎲 بهترین از رندوم</button>
						</div>
						<div class="loc-smart-result" id="loc-smart-result-${index}">${esc(state.smartMessage || "")}</div>
					</div>

				</div>
			</div>`;
			})
			.join("");
		// set country select values to current card's country
		list.forEach((entry, idx)=>{
			const sel = box.querySelector(`.loc-country-select[data-idx="${idx}"]`);
			const state = getLocState(root, idx);
			if(sel) sel.value = state.country || String(entry.country || "").toUpperCase();
			const protocol = box.querySelector(`.loc-protocol[data-idx="${idx}"]`);
			if(protocol) protocol.value = state.protocol;
		});
		box.querySelectorAll(".loc-toggle-btn").forEach(button => button.addEventListener("click", () => {
			const idx = Number(button.dataset.idx);
			root._expandedLoc = root._expandedLoc === idx ? null : idx;
			renderLocations(root);
		}));
		/* On-demand country detection — head icon and body button share it. */
		box.querySelectorAll(".loc-geo-detect").forEach(button => button.addEventListener("click", (event) => {
			event.stopPropagation();
			runGeoDetect(root, button);
		}));
		for (const [selector, key] of [[".loc-protocol", "protocol"], [".loc-country-select", "country"], [".loc-candidate-count", "count"]]) {
			box.querySelectorAll(selector).forEach(input => input.addEventListener("change", () => {
				const state = getLocState(root, Number(input.dataset.idx));
				state[key] = input.value;
				state.revision = (state.revision || 0) + 1;
				if (key === "protocol") { state.pool = []; state.message = ""; state.country = ""; renderLocations(root); }
			}));
		}
		box.querySelectorAll(".loc-fetch-pool").forEach(button => button.addEventListener("click", async () => {
			const state = getLocState(root, Number(button.dataset.idx));
			if (state.loading) return;
			const protocol = state.protocol;
			state.loading = true;
			renderLocations(root);
			try {
				const data = await api.post("/api/tools/public-proxies", {protocol, limit: 500});
				if (state.protocol !== protocol) return;
				state.pool = data.proxies || [];
				state.message = state.pool.length ? `${state.pool.length} پروکسی آماده است.` : "پروکسی‌ای پیدا نشد؛ دوباره تلاش کنید.";
			} catch(error) {
				if (state.protocol === protocol) state.message = error.message || "واکشی ناموفق بود.";
			} finally {
				state.loading = false;
				renderLocations(root);
			}
		}));
		// toggle handlers
		box.querySelectorAll("[data-toggle]").forEach(el=>{
			el.addEventListener("click", (e)=>{
				if(e.target.closest("button")) return;
				const idx = Number(el.dataset.toggle);
				root._expandedLoc = root._expandedLoc === idx ? null : idx;
				renderLocations(root);
			});
		});
		box.querySelectorAll("[data-loc-remove]").forEach((button) =>
			button.addEventListener("click", (e) => {
				e.stopPropagation();
				const idx = Number(button.dataset.locRemove);
				const next = readLocations(root);
				next.splice(idx, 1);
				root._locStates?.splice(idx, 1);
				// also shift test cache
				const newCache = new Map();
				for(const [k,v] of getLocTestCache(root)){
					if(k<idx) newCache.set(k, v);
					else if(k>idx) newCache.set(k-1, v);
				}
				root._locTestCache = newCache;
				if(root._expandedLoc === idx) root._expandedLoc = null;
				else if(root._expandedLoc !== null && root._expandedLoc > idx) root._expandedLoc--;
				writeLocations(root, next);
				toast("لوکیشن حذف شد — ذخیره کنید تا اعمال شود.", "ok");
			})
		);
		box.querySelectorAll(".loc-auto-replace").forEach(input => input.addEventListener("change", () => {
			const list = readLocations(root);
			const entry = list[Number(input.dataset.idx)];
			/* v3.0.3 — the switch is the operator's own opt-in, on any slot with a
			   known country; it is no longer limited to «public» picks. */
			entry.auto_replace = input.checked;
			writeLocations(root, list, false);
		}));
		// Keep the form value current without replacing the focused input on each keystroke.
		box.querySelectorAll(".loc-manual-input").forEach(input => {
			input.addEventListener("input", () => {
				const idx = Number(input.dataset.idx);
				const list = readLocations(root);
				const proxy = normalizeManualProxy(input.value);
				const slotState = root._locStates?.[idx];
				if (slotState) slotState.revision = (slotState.revision || 0) + 1;
				/* A hand-typed address is a manual slot again (the provenance of a
				   «public» pick is gone once it is edited), even when the text is
				   pasted back unchanged — but the switch above is the operator's,
				   so this never touches it. */
				list[idx].proxy = proxy;
				list[idx].source = "manual";
				/* The opt-in stays exactly as the operator set it; only the country
				   becomes unknown again, which is what disables the switch below
				   until the debounced detection fills it in. */
				/* A different address invalidates the previous country label; the
				   debounced lookup replaces it (and the server retries at save).
				   writeLocations must run BEFORE the head patch — the patch
				   re-reads the field, so patching ahead of the write would
				   resurrect the exact stale label it is supposed to clear. */
				list[idx].country = null;
				list[idx].country_name = null;
				writeLocations(root, list, false);
				patchLocCountryHead(root, idx);
				scheduleGeoDetect(root, idx, proxy);
				getLocTestCache(root).delete(idx);
				const card = input.closest(".loc-card");
				card.classList.toggle("is-empty", !proxy);
				const auto = card.querySelector(".loc-auto-replace");
				if (auto) { auto.checked = Boolean(list[idx].auto_replace); auto.disabled = true; }
				const tip = card.querySelector(".loc-auto-tip");
				if (tip) tip.setAttribute("data-tip", autoReplaceTip({ ...list[idx], country: null, proxy }));
				card.querySelector(".loc-proxy-empty").hidden = Boolean(proxy);
				card.querySelector(".loc-ping-wrap").innerHTML = proxy ? "" : '<span class="ds-badge ds-tone-warning">خالی</span>';
				/* New address ⇒ the geo row follows: button availability, picker
				   reset and a clean status line for the next detection. */
				card.querySelectorAll(".loc-geo-detect").forEach((b) => { b.disabled = !proxy; });
				patchGeoStatus(root, idx, "");
			});
		});
		// per-card single test — discard results after edits/deletion/new tests.
		box.querySelectorAll(".loc-test-single").forEach(btn => {
			btn.addEventListener("click", async () => {
				const idx = Number(btn.dataset.idx);
				if (!readLocations(root)[idx]?.proxy) { toast("این کارت هنوز پروکسی ندارد.", "err"); return; }
				const token = beginLocationTest(root, idx);
				renderLocations(root);
				try {
					const data = await api.post("/api/tools/test-proxy", {proxies:[token.proxy]});
					const result = data.results?.[0] || {ok:false, error:"نتیجه‌ای دریافت نشد"};
					finishLocationTest(root, token, result);
				} catch (error) {
					finishLocationTest(root, token, {ok:false, error:error.message});
				} finally { renderLocations(root); }
			});
		});
		// smart pick
		box.querySelectorAll(".loc-smart-pick").forEach(btn=>{
			btn.addEventListener("click", async()=>{
				const idx = Number(btn.dataset.idx);
				const countrySel = box.querySelector(`.loc-country-select[data-idx="${idx}"]`);
				const countInput = box.querySelector(`.loc-candidate-count[data-idx="${idx}"]`);
				const resultBox = box.querySelector(`#loc-smart-result-${idx}`);
				if (getLocState(root,idx).picking) return;
				const pool = getLocState(root, idx).pool;
				if(!pool.length){ toast("اول «واکشی فهرست کشورها» را بزنید.", "err"); return; }
				const wanted = String(countrySel.value||"").toUpperCase();
				if(!wanted){ toast("کشور را انتخاب کنید.", "err"); return; }
				const n = Math.max(3, Math.min(20, Number(countInput.value||10)));
				let candidates = pool.filter(e=> String(e.country||"").toUpperCase()===wanted);
				if(!candidates.length){ toast("برای این کشور پروکسی‌ای پیدا نشد.", "err"); return; }
				// shuffle and pick N
				candidates = shuffleArray(candidates).slice(0, Math.min(n, candidates.length));
				const list = readLocations(root);
				const beforePick = JSON.stringify(list[idx]);
				const slotState = getLocState(root, idx);
				const revision = slotState.revision;
				const known = new Set(list.map(e=>e.proxy));
				// filter out already used in other cards
				candidates = candidates.filter(c=> !known.has(c.url) || c.url===list[idx]?.proxy);
				if(!candidates.length){ toast("همه کاندیدها قبلا استفاده شده‌اند — دوباره واکشی کنید.", "err"); return; }
				btn.disabled = true;
				slotState.picking = true;
				slotState.smartMessage = "در حال بررسی کاندیدها…";
				resultBox.innerHTML = `<span class="ds-spinner" aria-hidden="true"></span> ${candidates.length} کاندید رندوم انتخاب شد — در حال پینگ همزمان...`;
				try{
					const data = await api.post("/api/tools/test-proxy", {proxies: candidates.map(c=>c.url)});
					const results = data.results || [];
					// attach country info
					const enriched = results.map((r,i)=> ({...r, country: candidates[i].country, country_name: candidates[i].country_name, url: candidates[i].url}));
					enriched.sort((a,b)=>{
						if(a.ok && !b.ok) return -1;
						if(!a.ok && b.ok) return 1;
						if(a.ok && b.ok) return a.latency - b.latency;
						return 0;
					});
					const best = enriched.find(r=>r.ok);
					if(!best){
						slotState.smartMessage = "هیچکدام سالم نبود؛ دوباره امتحان کنید یا کشور دیگر.";
						btn.disabled=false;
						return;
					}
					// Re-read after the asynchronous test; never overwrite another edit.
					const current = readLocations(root);
					if (root._locStates?.[idx] !== slotState || slotState.revision !== revision || JSON.stringify(current[idx]) !== beforePick) {
						slotState.smartMessage = "اسلات حین تست تغییر کرد؛ نتیجه قبلی اعمال نشد.";
						toast(slotState.smartMessage, "warn");
						return;
					}
					slotState.revision = (slotState.revision || 0) + 1;
					current[idx].source = "public";
					current[idx].auto_replace = current[idx].auto_replace === true;
					current[idx].proxy = best.proxy;
					current[idx].country = best.country || wanted;
					current[idx].country_name = best.country_name || null;
					writeLocations(root, current);
					setLocTestResult(root, idx, best);
					slotState.smartMessage = `بهترین از ${candidates.length} گزینه انتخاب شد — ${best.latency}ms`;
					toast(`بهترین از ${candidates.length} تا انتخاب شد — ${best.latency}ms ✅`, "ok");
					root._expandedLoc = idx;
					renderLocations(root);
				}catch(err){
					slotState.smartMessage = err.message || "انتخاب ناموفق بود.";
				} finally {
					slotState.picking = false;
					renderLocations(root);
				}
			});
		});
		if (focus) {
			const index = (root._locStates || []).indexOf(focus.state);
			const input = box.querySelector(`.loc-manual-input[data-idx="${index}"]`);
			if (input) {
				if (normalizeManualProxy(focus.value) === list[index]?.proxy) input.value = focus.value;
				input.focus(); input.setSelectionRange(focus.start,focus.end);
			}
		}
		/* A card that was just created opens with its field ready: the admin has
		   already decided to add a location, so the next keystroke belongs there
		   rather than in a card they have to hunt for. */
		if (root._focusLoc !== null && root._focusLoc !== undefined && root._focusLoc < list.length) {
			const input = box.querySelector(`.loc-manual-input[data-idx="${root._focusLoc}"]`);
			root._focusLoc = null;
			if (input && typeof input.focus === "function") {
				input.focus();
				if (typeof input.select === "function") input.select();
			}
		}
	}

	/* ── country pool + card wiring ──────────────────────────────── */
	function wirePublicProxies(root) {
		const addCardBtn = root.querySelector("#btn-add-location-card");
		const testAllBtn = root.querySelector("#btn-test-all-locs");
		if(root._expandedLoc === undefined) root._expandedLoc = null;

		if(addCardBtn){
			addCardBtn.addEventListener("click", () => {
				const list = readLocations(root);
				list.push({ proxy: "", country: null, country_name: null });
				/* The card is created empty on purpose — that is the slot the
				   admin fills in — and it opens focused. Saving is what refuses a
				   blank card, so one can never slip into the database. */
				root._expandedLoc = list.length - 1;
				root._focusLoc = list.length - 1;
				writeLocations(root, list);
				toast("اسلات لوکیشن اضافه شد — پروکسی را وارد کنید.", "ok");
			});
		}
		if (testAllBtn) {
			testAllBtn.addEventListener("click", async () => {
				const tokens = readLocations(root).flatMap((entry,index) => entry.proxy ? [beginLocationTest(root,index)] : []);
				if (!tokens.length) { toast("هیچ کارت پروکسی ندارد.", "err"); return; }
				testAllBtn.disabled = true;
				renderLocations(root);
				try {
					// The API accepts at most 30 proxies per request; do not silently skip extras.
					for (let offset=0; offset<tokens.length; offset+=30) {
						const batch = tokens.slice(offset,offset+30);
						try {
							const data = await api.post("/api/tools/test-proxy", {proxies:batch.map(token=>token.proxy)});
							const results = new Map((data.results || []).map(result=>[result.proxy,result]));
							batch.forEach(token=>finishLocationTest(root,token,results.get(token.proxy) || {ok:false,error:"نتیجه‌ای دریافت نشد"}));
						} catch(error) {
							batch.forEach(token=>finishLocationTest(root,token,{ok:false,error:error.message}));
						}
						renderLocations(root);
					}
				} finally { testAllBtn.disabled = false; }
			});
		}
		// initial render
		renderLocations(root);
	}

	/* ── the two anti-DPI modes ───────────────────────────────────────────
	   Both start OFF and they are mutually exclusive on purpose: either the
	   simple fragment pair, or the advanced TLS-Mask set (fm + cs + mask) that
	   PattNG/PattN expect. Turning one on clears and locks the other, so a
	   config can never carry two competing fragmentation strategies. Fields are
	   made readOnly rather than disabled — a disabled field drops out of
	   FormData, and then the server would keep the old value instead of clearing
	   it. */
	/* ── ports multi-select ────────────────────────────────────────────────────
	   Cloudflare answers on a fixed set of ports and only some of them carry TLS.
	   A free-text box let an operator type a port that cannot work in the selected
	   mode, which produced configs that never connected. The list now follows the
	   TLS select, and the choice is written to the hidden `port` input as the same
	   comma-separated string the backend and the link builder already use — so
	   nothing downstream changes. The port lists come from window.DEVCOP, i.e. from
	   src/config.js, the same source the subscription generator checks. */
	function wirePorts(root) {
		const tlsSelect = root.querySelector("#tls-select");
		const button = root.querySelector("#ports-btn");
		const pop = root.querySelector("#ports-pop");
		const value = root.querySelector("#ports-val");
		const hidden = root.querySelector("#port-input");
		if (!tlsSelect || !button || !pop || !value || !hidden) return;

		const boot = window.DEVCOP || {};
		const FALLBACK = { tls: ["443", "2053", "2083", "2087", "2096", "8443"], none: ["80", "8080", "8880", "2052", "2082", "2086", "2095"] };
		const FAMILIES = {
			tls: { ports: (Array.isArray(boot.tls_ports) && boot.tls_ports.length ? boot.tls_ports : FALLBACK.tls).map(String), label: "فقط پورت‌های TLS کلودفلر" },
			none: { ports: (Array.isArray(boot.plain_ports) && boot.plain_ports.length ? boot.plain_ports : FALLBACK.none).map(String), label: "فقط پورت‌های غیر TLS کلودفلر" },
		};
		const family = () => FAMILIES[tlsSelect.value] || FAMILIES.tls;

		const parse = () => String(hidden.value || "").split(",").map((port) => port.trim()).filter(Boolean);

		function paint() {
			const focusedPort = pop.contains(document.activeElement) ? document.activeElement.value : null;
			const list = family().ports;
			const picked = parse();
			pop.innerHTML =
				`<div class="ds-port-heading">${family().label}</div>` +
				list
					.map(
						(port) => `<label class="ds-check">
							<span class="ds-check-control"><input type="checkbox" aria-label="پورت ${esc(port)}" value="${esc(port)}" ${picked.includes(port) ? "checked" : ""}><span class="ds-check-box" aria-hidden="true">${icon("check")}</span></span>
							<span class="ds-port-number">${esc(port)}</span>
							<span class="ds-port-note">${port === list[0] ? "پیش‌فرض" : ""}</span>
						</label>`
					)
					.join("");
			const shown = list.filter((port) => picked.includes(port));
			value.textContent = shown.length ? shown.join("، ") : "— انتخاب کنید —";
			value.classList.toggle("is-empty", !shown.length);
			if (focusedPort) Array.from(pop.querySelectorAll("input")).find((input) => input.value === focusedPort)?.focus();
		}

		function commit() {
			hidden.value = Array.from(pop.querySelectorAll("input:checked")).map((el) => el.value).join(",");
			paint();
		}

		/* Switching TLS mode drops ports that cannot work in the new one; if that
		   leaves nothing, fall back to the family's first port so a config is never
		   generated without a port. */
		function reconcile() {
			const list = family().ports;
			const kept = parse().filter((port) => list.includes(port));
			hidden.value = (kept.length ? kept : [list[0]]).join(",");
			paint();
		}

		const setOpen = (on) => {
			pop.hidden = !on;
			button.setAttribute("aria-expanded", on ? "true" : "false");
		};

		/* One global closer for every dropdown on the page — registered once, not
		   once per modal, so opening the form repeatedly cannot stack handlers. */
		if (!window.__dcMs) {
			window.__dcMs = true;
			const closeAll = (except) => {
				for (const open of Array.from(document.querySelectorAll(".ds-port-menu:not([hidden])"))) {
					const ms = open.closest(".ds-port-select");
					if (ms === except) continue;
					open.hidden = true;
					const btn = ms && ms.querySelector(".ds-port-trigger");
					if (btn) btn.setAttribute("aria-expanded", "false");
				}
			};
			document.addEventListener("click", (event) => {
				const ms = event.target && event.target.closest ? event.target.closest(".ds-port-select") : null;
				closeAll(ms);
			});
			document.addEventListener("keydown", (event) => {
				if (event.key !== "Escape" || event.defaultPrevented) return;
				const open = Array.from(document.querySelectorAll(".ds-port-menu:not([hidden])")).find((menu) => !menu.closest("[hidden],[inert]"));
				if (open) { event.preventDefault(); event.stopImmediatePropagation(); const trigger = open.closest(".ds-port-select")?.querySelector(".ds-port-trigger"); closeAll(null); trigger?.focus(); }
			}, true);
		}

		pop.addEventListener("change", commit);
		button.addEventListener("click", () => setOpen(pop.hidden));
		button.addEventListener("keydown", (event) => { if (event.key === "ArrowDown") { event.preventDefault(); setOpen(true); pop.querySelector("input")?.focus(); } });
		pop.addEventListener("keydown", (event) => {
			if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
			event.preventDefault(); const inputs = Array.from(pop.querySelectorAll("input")); const at = inputs.indexOf(document.activeElement);
			const next = event.key === "Home" ? 0 : event.key === "End" ? inputs.length - 1 : (at + (event.key === "ArrowDown" ? 1 : -1) + inputs.length) % inputs.length;
			inputs[next]?.focus();
		});
		tlsSelect.addEventListener("change", reconcile);
		reconcile();
	}

	function wireDpiModes(root) {
		const fragmentSwitch = root.querySelector("#mode-fragment");
		const maskSwitch = root.querySelector("#mode-tlsmask");
		if (!fragmentSwitch || !maskSwitch) return;

		const MODE_FIELDS = { fragment: ["frag_len", "frag_int"], tlsmask: ["advanced_frag", "cipher_suites", "tls_mask"] };
		const fieldOf = (key) => root.querySelector(`[name="${key}"]`);
		const clearMode = (mode) => {
			for (const key of MODE_FIELDS[mode]) {
				const field = fieldOf(key);
				if (field) field.value = "";
			}
		};
		const sync = () => {
			for (const mode of ["fragment", "tlsmask"]) {
				const on = mode === "fragment" ? fragmentSwitch.checked : maskSwitch.checked;
				for (const key of MODE_FIELDS[mode]) {
					const field = fieldOf(key);
					if (!field) continue;
					field.readOnly = !on;
					field.classList.toggle("locked", !on);
				}
				const body = root.querySelector(`[data-mode-body="${mode}"]`);
				if (body) body.classList.toggle("off", !on);
			}
			const preset = root.querySelector("#dpi-preset");
			const apply = root.querySelector("#dpi-preset-apply");
			if (preset) preset.disabled = !fragmentSwitch.checked;
			if (apply) apply.disabled = !fragmentSwitch.checked;
			root.querySelectorAll("[data-patterniha]").forEach((button) => {
				button.disabled = !maskSwitch.checked;
			});
		};

		fragmentSwitch.addEventListener("change", () => {
			if (fragmentSwitch.checked) {
				maskSwitch.checked = false;
				clearMode("tlsmask");
				const len = fieldOf("frag_len");
				const gap = fieldOf("frag_int");
				if (len && !String(len.value).trim()) len.value = "200-3000";
				if (gap && !String(gap.value).trim()) gap.value = "1-2";
			} else {
				clearMode("fragment");
			}
			sync();
		});

		maskSwitch.addEventListener("change", () => {
			if (maskSwitch.checked) {
				fragmentSwitch.checked = false;
				clearMode("fragment");
			} else {
				clearMode("tlsmask");
			}
			sync();
		});

		sync();
	}

	/* ── hover/focus hints ──────────────────────────────────────────────
	   One floating bubble appended to <body> and positioned with fixed
	   coordinates. Doing it in JS rather than a CSS ::after is deliberate: the
	   panel renders inside scrollable cards and modals, whose overflow would
	   clip a pure-CSS tooltip. Listeners are delegated on document, so markers
	   added later (every modal, tab switch or re-render) work with no rebinding.
	   Touch has no hover, so a tap toggles the same bubble. */
	function initTooltips() {
		window.DevCopUI.initTooltips();
	}

	/* A hint is either a plain string (informational, «؟» badge) or
	   { t: text, warn: true } for anything that can break a working config
	   (amber «⚠» badge). */
	function hintMarkup(entry, extraClass) {
		const text = typeof entry === "string" ? entry : entry.t;
		const warn = typeof entry === "string" ? false : Boolean(entry.warn);
		/* v2.3.6 — { danger: true } is the red pulsing variant for warnings
		   the operator must not miss (e.g. «scan without VPN»). */
		const danger = typeof entry === "string" ? false : Boolean(entry.danger);
		const look = danger ? " danger" : warn ? " warn" : "";
		return `<span class="hint${look}${extraClass ? " " + extraClass : ""}" data-tip="${esc(text)}" tabindex="0" role="note" aria-label="توضیح">${danger || warn ? "⚠" : "؟"}</span>`;
	}

