	function injectHints(root) {
		if (!root || !root.querySelector) return;
		for (const [key, entry] of Object.entries(FIELD_HINTS)) {
			const field = root.querySelector(`[name="${key}"], [data-setting="${key}"]`);
			if (!field) continue;
			const box = field.closest(".ds-switch") || field.closest("label, .ds-field");
			if (!box) continue;
			const anchor = box.querySelector(".ds-field-label,.ds-switch-text,.txt");
			if (!anchor || anchor.querySelector(".hint")) continue;
			anchor.insertAdjacentHTML("beforeend", hintMarkup(entry));
		}
	}

	/* ── Patterniha anti-filtering profiles ──────────────────────────────
	   PattNG (Android, a v2rayNG fork) and PattN (desktop, a v2rayN fork)
	   understand three share-link parameters that stock clients do not:
	     fp=unsafe → trust the cipher suites we send instead of a browser uTLS profile
	     cs=…      → colon-separated TLS cipher suite list
	     fm=…      → "FinalMask": URL-encoded JSON describing the fragment stages
	   Filling exactly these three makes a config produced here work in those
	   clients with no manual editing. The CDN address is deliberately not part of
	   the profile: it comes from this user's clean-IP pool (the «آیپی و لوکیشن»
	   tab), which the panel already rotates. These are the interoperability
	   constants published for those clients; every field stays editable. */
	/* Only the two parameters that the Patterniha method actually defines are
	   filled: fm (FinalMask) and cs (cipher suites). `mask` is camouflage and is
	   deliberately left to the admin, and fp is no longer touched because unsafe
	   is now the panel-wide default. Values are the live defaults of the
	   reference tool — cf-optimizor (https://github.com/ArasTey/cf-optimizor,
	   author: Aras) — used with the author's permission. */
	/* Which revision of that tool the values below were taken from: one stamp,
	   so the panel can never claim a freshness it does not have. `npm run
	   check:cf` re-reads upstream and compares; `npm run fix:cf` writes the
	   values and this stamp together. The credit line in the form shows it. */
	const CF_OPTIMIZOR = { repo: "ArasTey/cf-optimizor", branch: "main", commit: "5c1c18b", date: "2026-09-10" };
	/* JSON.stringify keeps `fm` compact; PattNG/PattN parse it as JSON, so
	   whitespace is not part of the contract — and the share link stays short. */
	const PATTERNIHA = {
		/* عادی — the reference tool's live defaults (two fragment stages). */
		normal: {
			cipher_suites: [
				"TLS_AES_256_GCM_SHA384",
				"TLS_CHACHA20_POLY1305_SHA256",
				"TLS_AES_128_GCM_SHA256",
				"TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384",
				"TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
				"TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
				"TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
				"TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256",
				"TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256",
				"TLS_ECDHE_ECDSA_WITH_AES_256_CBC_SHA",
				"TLS_ECDHE_RSA_WITH_AES_256_CBC_SHA",
				"TLS_ECDHE_ECDSA_WITH_AES_128_CBC_SHA256",
				"TLS_ECDHE_RSA_WITH_AES_128_CBC_SHA256",
			].join(":"),
			advanced_frag: JSON.stringify({ tcp: [
				{ type: "fragment", settings: { packets: "tlshello", lengths: ["0", "104", "1"], delays: ["0"], maxSplit: "0" } },
				{ type: "fragment", settings: { packets: "1-1", lengths: ["114", "1"], delays: ["1"], maxSplit: "11" } },
			] }),
		},
		/* سبک — «Aras Mode»: one stage with a shorter suite list, for
		   Instagram-like traffic where speed beats maximum fragmentation. */
		light: {
			cipher_suites: [
				"TLS_AES_128_GCM_SHA256",
				"TLS_AES_256_GCM_SHA384",
				"TLS_CHACHA20_POLY1305_SHA256",
			].join(":"),
			advanced_frag: JSON.stringify({ tcp: [
				{ type: "fragment", settings: { packets: "tlshello", lengths: ["1-1"], delays: ["0"], maxSplit: "0" } },
			] }),
		},
	};

	/* One filler for both places the anti-DPI fields live: the user modal binds
	   inputs with name=…, the settings page with data-setting="default_…". */
	function fillPatterniha(root, profileId, { attr = "name", prefix = "" } = {}) {
		const profile = PATTERNIHA[profileId];
		if (!profile) return;
		let touched = 0;
		for (const [key, value] of Object.entries(profile)) {
			const field = root.querySelector(`[${attr}="${prefix}${key}"]`);
			if (!field) continue;
			field.value = value;
			touched += 1;
		}
		if (!touched) return toast("فیلدهای ضد DPI در این صفحه پیدا نشد.", "err");
		const which = profileId === "light" ? "حالت سبک Patterniha" : "مقادیر ضد فیلترینگ Patterniha";
		toast(`${which} پر شد ✅ — ذخیره کنید تا در کانفیگ‌ها بنشیند.`, "ok");
	}

	/* A fresh UUID for the new-user form. */
	function newUuid() {
		if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
		return uuidFallback();
	}

	/* Operator starting points for the *fragment* mode only. Each entry fills
	   just the fragment length/interval pair, so applying one can never silently
	   turn on the other mode. The Patterniha values are not presets — they live
	   behind the TLS-Mask switch, which is where they belong. */
	const DPI_PRESETS = [
		{ id: "balanced", label: "⚖️ متعادل — طول 200-3000 / فاصله 1-2", frag_len: "200-3000", frag_int: "1-2" },
		{ id: "mci", label: "📶 همراه اول — طول 100-200 / فاصله 1-1", frag_len: "100-200", frag_int: "1-1" },
		{ id: "irancell", label: "📶 ایرانسل — طول 1-3 / فاصله 1-2", frag_len: "1-3", frag_int: "1-2" },
		{ id: "rightel", label: "📶 رایتل — طول 200-500 / فاصله 2-4", frag_len: "200-500", frag_int: "2-4" },
		{ id: "mokhaberat", label: "📶 مخابرات / ADSL — طول 500-1000 / فاصله 1-3", frag_len: "500-1000", frag_int: "1-3" },
	];

	function applyDpiPreset(root) {
		const select = root.querySelector("#dpi-preset");
		const button = root.querySelector("#dpi-preset-apply");
		if (!select || !button) return;
		button.addEventListener("click", () => {
			const preset = DPI_PRESETS.find((entry) => entry.id === select.value);
			if (!preset) return toast("اول یک پریست انتخاب کنید.", "err");
			for (const key of ["frag_len", "frag_int"]) {
				const field = root.querySelector(`[name="${key}"]`);
				if (field) field.value = preset[key] || "";
			}
			toast(`پریست «${preset.label}» اعمال شد ✅`, "ok");
		});
	}

	/* ── modal engine ─────────────────────────────────────────────────── */
	/* The production design-system controller owns focus, inert and scroll
	   locking. Domain callers keep the same {root, body, foot, close} API. */
	function openModal(options) {
		return window.DevCopUI.openModal(options);
	}
	function confirmDialog(message, { title = "تأیید عملیات", danger = true, confirmText = "انجام شود" } = {}) {
		return new Promise((resolve) => {
			const modal = openModal({
				title,
				size: "sm",
				center: true,
				body: `<p class="ds-mb-2">${esc(message)}</p>`,
				footer: `<button class="ds-btn ${danger ? "is-danger" : "is-primary"}" data-yes>${esc(confirmText)}</button><button class="ds-btn is-ghost" data-no>انصراف</button>`,
				onClose: () => resolve(false),
			});
			$("[data-yes]", modal.root).addEventListener("click", () => {
				modal.root.removeEventListener("click", noop);
				resolve(true);
				modal.close();
			});
			$("[data-no]", modal.root).addEventListener("click", () => {
				resolve(false);
				modal.close();
			});
			function noop() {}
		});
	}

	function numberDialog(title, value) {
		return new Promise((resolve) => {
			const modal = openModal({ title, size: "sm", center: true, body: `<label class="ds-field"><span class="ds-field-label">مقدار</span><input class="ds-input" type="number" min="1" step="1" value="${value}" data-amount autofocus></label>`, footer: '<button class="ds-btn is-primary" type="button" data-amount-save>اعمال</button><button class="ds-btn is-ghost" type="button" data-close>انصراف</button>', onClose: () => resolve(null) });
			const input = $("[data-amount]", modal.root);
			const save = () => { if (!input.checkValidity()) { input.reportValidity(); return; } resolve(input.value); modal.close(); };
			$("[data-amount-save]", modal.root).addEventListener("click", save);
			input.addEventListener("keydown", (event) => { if (event.key === "Enter") { event.preventDefault(); save(); } });
		});
	}

	/* ── کانال تلگرام ──────────────────────────────────────────────────
	   The channel is the one place the panel points its user at, and this
	   dialog is the only surface that advertises it: centred, dimmed backdrop,
	   faded in, and shown on *every* entry to the panel — a panel may have a
	   single user who never opens a status page, so this is the one moment the
	   invitation is guaranteed to be seen. The address comes from the panel's
	   own «لینک کانال» setting, so it follows the panel, not this file; only
	   real Telegram hosts are accepted (the setting is hand-typed, and a dialog
	   that could be pointed anywhere is a phishing surface). */
	function channelInviteLink(raw) {
		const value = String(raw || "").trim();
		if (!value) return "";
		const withScheme = /^https?:\/\//i.test(value) ? value : `https://${value}`;
		try {
			const url = new URL(withScheme);
			if (!/(^|\.)t\.me$|(^|\.)telegram\.(me|org)$/i.test(url.hostname)) return "";
			return url.toString();
		} catch {
			return "";
		}
	}
	function maybeShowChannelInvite() {
		const link = channelInviteLink(state.settings?.brand_channel);
		if (!link) return;
		openModal({
			title: "کانال تلگرام Bee.Hive",
			size: "sm",
			center: true,
			dim: true,
			body: `<div class="channel-invite">
				<p class="channel-invite-text">برای اطلاع از آخرین آپدیت‌ها، رفع اشکالات و ارتباط با ما به کانال تلگرامی ما بپیوندید.</p>
				<a class="ds-btn is-primary channel-invite-join" href="${esc(link)}" target="_blank" rel="noopener">${icon("link")}<span>پیوستن به کانال</span></a>
				<button class="ds-btn is-ghost channel-invite-close" data-close>بستن</button>
			</div>`,
		});
	}

	/* ── نصب PWA ────────────────────────────────────────────────────────
	   A small banner at the top of the panel asks to install the app. Shown
	   only while the browser says the app is installable (or on iOS, where
	   installing is a manual Safari step), never inside an iframe, never when
	   the app already runs installed, and never again once «دیگر نشان نده»
	   is pressed. The × only silences it until the next session. */
	const PWA_HINT_KEY = "devcop-pwa-hint";
	let installPrompt = null;
	function pwaStandalone() {
		try { return Boolean(window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) || window.navigator.standalone === true; } catch { return false; }
	}
	function pwaHidden() {
		try {
			if (localStorage.getItem(PWA_HINT_KEY) === "never") return true;
			if (sessionStorage.getItem(PWA_HINT_KEY) === "closed") return true;
		} catch {}
		return false;
	}
	function pwaEmbedded() {
		try { return window.self !== window.top; } catch { return true; }
	}
	function hideInstallBanner(forever) {
		const banner = $("#pwa-banner");
		if (banner) banner.remove();
		try { if (forever) localStorage.setItem(PWA_HINT_KEY, "never"); else sessionStorage.setItem(PWA_HINT_KEY, "closed"); } catch {}
	}
	function showInstallBanner() {
		if (pwaStandalone() || pwaHidden() || pwaEmbedded() || !state.settings) return;
		if ($("#pwa-banner")) return;
		const main = $(".main");
		const topbar = main && main.querySelector(".ds-appbar");
		if (!main || !topbar) return;
		/* iOS Safari has no install prompt at all; there the banner is a short
		   instruction instead of a button that could only fail. */
		const ios = /iphone|ipad|ipod/i.test(navigator.userAgent || "");
		const banner = document.createElement("div");
		banner.className = "ds-banner ds-tone-info is-inline pwa-banner";
		banner.id = "pwa-banner";
		banner.innerHTML = `
			<span class="pwa-text">${icon("sparkles")}<span>پنل را به عنوان یک اپلیکیشن نصب کن  — سریع‌تر باز میشه و تمام‌ صفحه است!${ios ? " در Safari: دکمه‌ی اشتراک‌گذاری → «افزودن به صفحه‌ی اصلی»." : ""}</span></span>
			<span class="ds-actions">
				${ios ? "" : `<button class="ds-btn is-sm is-primary" id="pwa-install">${icon("download")}<span>نصب</span></button>`}
				<button class="ds-btn is-sm is-ghost" id="pwa-never">دیگر نشان نده</button>
				<button class="ds-btn is-sm is-ghost pwa-x" id="pwa-later" type="button" title="بستن" aria-label="بستن">${icon("x")}</button>
			</span>`;
		topbar.insertAdjacentElement("afterend", banner);
		const install = $("#pwa-install", banner);
		if (install) install.addEventListener("click", async () => {
			if (!installPrompt) return;
			installPrompt.prompt();
			try { await installPrompt.userChoice; } catch {}
			installPrompt = null;
			hideInstallBanner(false);
		});
		$("#pwa-later", banner).addEventListener("click", () => hideInstallBanner(false));
		$("#pwa-never", banner).addEventListener("click", () => hideInstallBanner(true));
	}
	window.addEventListener("beforeinstallprompt", (event) => {
		event.preventDefault();
		installPrompt = event;
		showInstallBanner();
	});
	window.addEventListener("appinstalled", () => hideInstallBanner(true));

	/* ── state ────────────────────────────────────────────────────────── */
	const state = {
		page: "dashboard",
		users: [],
		total: 0,
		stats: null,
		requests: null,
		settings: null,
		pool: [],
		/* Named clean-IP pools (v2.3.0) — [{name, created_at, ips[]}] from /api/ip-pools. */
		pools: [],
		/* Live scanner state — survives page switches so a running scan keeps
		   collecting and the results/selection re-render when you come back. */
		scan: null,
		defaults: {},
		search: "",
		order: "created_at",
		selected: new Set(),
		loading: false,
	};

	/* ── navigation ───────────────────────────────────────────────────── */
	const PAGE_TITLES = {
		dashboard: "داشبورد",
		users: "کاربران",
		ips: "آیپی تمیز",
		tools: "ابزارها",
		settings: "تنظیمات",
		"external-configs": "External Raw Configs",
		backup: "پشتیبان‌گیری",
		update: "نسخه و به‌روزرسانی",
		help: "راهنما",
	};

	function go(page) {
		if (!Object.hasOwn(PAGE_TITLES, page)) page = "dashboard";
		state.page = page;
		$$(".ds-drawer-item[data-page]").forEach((item) => {
			const active = item.dataset.page === page;
			item.classList.toggle("is-active", active);
			if (active) item.setAttribute("aria-current", "page"); else item.removeAttribute("aria-current");
		});
		$$(".page").forEach((section) => { const active = section.id === `page-${page}`; section.classList.toggle("active", active); section.hidden = !active; });
		$("#page-title").textContent = PAGE_TITLES[page];
		render();
		window.scrollTo(0, 0);
	}

	/* ── data loading ─────────────────────────────────────────────────── */
	let usersRequestId = 0;
	async function loadUsers() {
		const requestId = ++usersRequestId;
		const params = new URLSearchParams({ search: state.search, order: state.order, limit: "500" });
		const data = await api.get(`/api/users?${params}`);
		if (requestId !== usersRequestId) return;
		state.users = data.users || [];
		state.total = data.total || 0;
		state.stats = data.stats || null;
		state.defaults = data.defaults || {};
		state.selected = new Set([...state.selected].filter((name) => state.users.some((user) => user.username === name)));
	}
	async function loadOverview() {
		const data = await api.get("/api/overview");
		state.stats = data.stats;
		state.requests = data.requests;
		state.settings = data.settings;
	}
	async function loadSettings() {
		const data = await api.get("/api/settings");
		state.settings = data.settings;
		state.blocklist = data.blocklist || null; /* v2.3.5: builtin baseline count for the filter card */
		state.integrity = data.integrity || null; /* v2.3.14: ownership-lock status for the red banner */
		paintLockBanner();
		return data;
	}
	async function loadPool() {
		const data = await api.get("/api/ip-pool");
		state.pool = data.pool || [];
	}

	async function loadPools() {
		const data = await api.get("/api/ip-pools");
		state.pools = data.pools || [];
	}
	async function refreshAll() {
		state.loading = true;
		try {
			await Promise.all([loadUsers(), loadOverview(), loadPool(), loadPools()]);
		} catch (error) {
			if (error.message !== "unauthorized") toast(error.message, "err");
		} finally {
			state.loading = false;
		}
	}

	let refreshingUsage = false;
	function canRefreshUsage() {
		return !document.hidden && !state.loading &&
			["dashboard", "users"].includes(state.page) &&
			!$(".ds-modal.is-open") &&
			!document.activeElement?.closest("input, select, textarea, [contenteditable]");
	}
	async function refreshUsage() {
		if (refreshingUsage || !canRefreshUsage()) return;
		refreshingUsage = true;
		try {
			await loadUsers();
			await loadOverview();
			// Do not replace a form/search field the operator focused during the request.
			if (canRefreshUsage()) render();
		} catch {
			// Keep the last successful snapshot; never turn a network error into zero usage.
		} finally {
			refreshingUsage = false;
		}
	}

	/* v2.3.6 — a subscription is over when its time ran out OR its volume /
	   request quota did (v2.3.3 stops those users); the «منقضی شده» card and
	   the users table must agree with each other on this. */
	function isQuotaDone(user) {
		return (Number(user.limit_gb) > 0 && Number(user.used_gb) >= Number(user.limit_gb)) ||
			(Number(user.limit_req) > 0 && Number(user.used_req) >= Number(user.limit_req));
	}
	/* v2.3.6 — «زمان همگام‌سازی» (1–5 minutes) drives both the online-device
	   window (server-side) and this client's own auto-refresh cadence: the
	   dashboard polling costs Cloudflare requests too, so it follows the
	   same knob instead of a hardcoded 30 s. */
	function syncMinutes() {
		const value = Math.round(Number(state.settings?.sync_interval) || 5);
		return Math.max(1, Math.min(5, Number.isFinite(value) ? value : 5));
	}
	let usageTimer = null;
	function armUsageSync() {
		if (usageTimer) clearInterval(usageTimer);
		usageTimer = setInterval(refreshUsage, syncMinutes() * 60_000);
	}

	/* ── dashboard ────────────────────────────────────────────────────── */
	function renderDashboard() {
		const stats = state.stats || {};
		const requests = state.requests || { daily: 0, total: 0, percent: 0 };
		const online = state.users.reduce((sum, user) => sum + Number(user.online_devices || 0), 0);
		/* v2.3.6 — time-, volume- and request-expired subscriptions all count
		   as «منقضی شده», matching what actually stopped the subscription. */
		const expired = state.users.filter((user) => user.remaining_days === 0 || isQuotaDone(user)).length;
		const inactive = Number(stats.total || 0) - Number(stats.active || 0);
		const reqPercent = Math.min(100, Number(requests.percent || 0));
		const reqClass = reqPercent > 85 ? "danger" : reqPercent > 60 ? "warn" : "ok";
		const reqTone = reqClass === "danger" ? "ds-tone-danger" : reqClass === "warn" ? "ds-tone-warning" : "ds-tone-success";

		return `
		<div class="ds-grid is-layout cols-4 stat-row ds-mb-4">
			<div class="ds-card stat"><span class="label">کاربران</span><span class="value">${fa(num(stats.total))}</span><span class="sub">${fa(num(stats.active))} فعال · ${fa(num(inactive))} غیرفعال</span></div>
			<div class="ds-card stat ds-tone-success has-action"><span class="label">حجم مصرفی (دوره جاری) ${hintMarkup("مصرف همه‌ی کاربران در دوره‌ی جاری.\n«مجموعاً» از اول کار است و با ریست صفر نمی‌شود.")}</span><span class="value">${gbOnly(stats.used_gb)}</span><span class="sub">مجموعاً <bdi>${gbOnly(stats.lifetime_gb)}</bdi></span><button class="ds-btn is-sm is-icon is-ghost stat-action" id="btn-reset-usage" title="ریست حجم دوره" aria-label="ریست حجم دوره"><svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg></button></div>
			<div class="ds-card stat"><span class="label">دستگاه‌های آنلاین</span><span class="value">${fa(num(online))}</span><span class="sub">بر اساس IP در ${fa(syncMinutes())} دقیقه اخیر (زمان همگام‌سازی)</span></div>
			<div class="ds-card stat${expired ? " ds-tone-warning" : ""}"><span class="label">منقضی شده</span><span class="value">${fa(num(expired))}</span><span class="sub">نیازمند تمدید/ریست کاربر</span></div>
		</div>

		<div class="ds-grid is-layout cols-2 is-equal ds-mb-4">
			<div class="ds-card">
				<h3 class="ds-card-title ds-feedback-row"><svg class="ico inline" aria-hidden="true"><use href="#i-cloud"/></svg> تعداد درخواست‌های کلودفلر ${hintMarkup(`سهمیه روزانه ${fa(num(CF_LIMIT))}`)}</h3>
				<div class="metric ds-mb-2">
					<div class="ds-progress ${reqTone} ds-flex-1" role="progressbar" aria-label="مصرف درخواست روزانه" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(reqPercent)}"><div class="ds-progress-track"><div class="ds-progress-fill" style="--ds-progress:${(reqPercent / 100).toFixed(3)}"></div></div></div>
					<small>${num(requests.percent, 1)}٪</small>
				</div>
				<dl class="kv">
					<dt>امروز</dt><dd>${num(requests.daily)} درخواست</dd>
					<dt>مجموع</dt><dd class="ds-row">${num(requests.total)} درخواست <button class="ds-btn is-sm is-icon is-ghost" id="btn-reset-requests-total" title="ریست شمارش کل" aria-label="ریست شمارش کل"><svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg></button></dd>
					<dt>بازنشانی</dt><dd>۰۳:۳۰ به‌وقت تهران</dd>
				</dl>
				${reqPercent > 80 ? '<div class="ds-banner ds-tone-danger is-inline ds-mt-3">⚠️ به سقف روزانه نزدیک می‌شوید؛ در صورت عبور، Worker تا ساعت ۰۳:۳۰ به‌وقت تهران از کار می‌افتد.</div>' : ""}
			</div>
			<div class="ds-card">
				<h3 class="ds-card-title ds-feedback-row"><svg class="ico inline" aria-hidden="true"><use href="#i-bolt"/></svg> عملیات سریع</h3>
				<div class="ds-actions dash-quick">
					<button class="ds-btn is-primary is-sm" data-act="add-user"><svg class="ico" aria-hidden="true"><use href="#i-plus"/></svg><span>کاربر جدید</span></button>
					<button class="ds-btn is-success is-sm quick-create-btn" data-act="add-quick-user" title="ساخت خودکار کاربر با چهار خروج واقعی کم‌پینگ"><svg class="ico" aria-hidden="true"><use href="#i-bolt"/></svg><span>ساخت سریع کاربر</span></button>
					<button class="ds-btn is-sm" data-act="run-jobs"><svg class="ico" aria-hidden="true"><use href="#i-refresh"/></svg><span>اجرای ریست/چرخش IP</span></button>
					<button class="ds-btn is-sm" data-act="flush"><svg class="ico" aria-hidden="true"><use href="#i-save"/></svg><span>ثبت آمار معوق</span></button>
