		</div>

		<div class="ds-card">
			<h3 class="ds-card-title ds-feedback-row"><svg class="ico inline" aria-hidden="true"><use href="#i-bars"/></svg> پرمصرف‌ترین کاربران ${hintMarkup("بر اساس حجم دوره جاری")}</h3>
			${renderUsersTable([...state.users].sort((a, b) => (b.used_gb || 0) - (a.used_gb || 0)).slice(0, 8), { compact: true })}
