	/* ── user form modal ──────────────────────────────────────────────── */
	function userFormModal(existing) {
		const user = existing || {};
		const d = state.defaults;
		const isEdit = Boolean(existing);
		const protocols = String(user.connection_type || d.connection_type || "vless").split("+");
		const poolOperators = [...new Set(state.pool.map((entry) => entry.operator))];
		/* v2.3.0: the select offers the named pools first (value "pool:<name>"),
		   then the legacy operator groups of the global pool. */
		const namedPools = state.pools || [];
		/* v2.3.2: «همه» maps to ip_pool '*' (union of every named pool) and
		   «آیپی‌های دستی» maps to ip_operator 'manual' (rotation never touches
		   the user — only the IPs typed into the clean-IPs box are used). */
		const poolSelectValue = user.ip_pool === "*" ? "all"
			: user.ip_pool ? `pool:${user.ip_pool}`
			: user.ip_operator === "manual" ? "manual"
			: user.ip_operator || "manual"; /* v2.3.3: new users start manual */

		const val = (key, fallback = "") => esc(user[key] !== undefined && user[key] !== null ? user[key] : fallback);
		const checked = (key, fallback = 0) => (user[key] !== undefined ? Number(user[key]) === 1 : Number(fallback) === 1);
		/* The required asterisk goes *after* the label text, so under RTL it lands on
		   the left of the words instead of floating to the wrong side. `opts.ph` puts
		   an example inside the box as a faint placeholder — the operator asked for
		   the short examples to live in the field, not under it. */
		const req = (on) => (on ? '<span class="req" aria-hidden="true">*</span>' : "");
		const input = (key, label, tip, type = "text", fallback = "", opts = {}) => `
			<label class="ds-field${opts.cls ? ` ${opts.cls}` : ""}"><span class="ds-field-label">${label}${req(opts.required)}</span>
				<input class="ds-input" type="${type}" name="${key}" value="${val(key, fallback)}"${opts.ph ? ` placeholder="${esc(opts.ph)}"` : ""} ${type === "number" ? 'step="any"' : ""}${opts.required ? ' aria-required="true"' : ""}>
				${tip ? `<span class="ds-field-help">${tip}</span>` : ""}</label>`;
		const area = (key, label, tip, rows = 4, fallback = "", opts = {}) => `
			<label class="ds-field full${opts.cls ? ` ${opts.cls}` : ""}"><span class="ds-field-label">${label}${req(opts.required)}</span>
				<textarea name="${key}" rows="${rows}" class="ds-input is-mono mono"${opts.ph ? ` placeholder="${esc(opts.ph)}"` : ""}>${val(key, fallback)}</textarea>
				${tip ? `<span class="ds-field-help">${tip}</span>` : ""}</label>`;
		const sw = (key, label, tip, fallback = 0) => `
			<div class="ds-switch"><label class="ds-switch-control"><input type="checkbox" name="${key}" ${checked(key, fallback) ? "checked" : ""} role="switch" aria-label="${esc(label)}"><span class="ds-switch-track" aria-hidden="true"></span></label><span class="ds-switch-text">${label}</span></div>
			${tip ? `<span class="ds-field-help dim ds-switch-help">${tip}</span>` : ""}`;
		/* Text is outside the control label, so selecting it cannot toggle a switch. */
		const swField = (key, label, tip, fallback = 0, cls = "") => `
			<div class="ds-field${cls ? ` ${cls}` : ""}">${sw(key, label, tip, fallback)}</div>`;

		const body = `
		<form id="user-form">
			<div class="ds-tabbar">
				<button class="ds-tabbar-item is-active" type="button" data-tab="basic"><svg class="ico inline" aria-hidden="true"><use href="#i-grid"/></svg> تنظیمات پایه</button>
				<button class="ds-tabbar-item" type="button" data-tab="quota"><svg class="ico inline" aria-hidden="true"><use href="#i-gauge"/></svg> سهمیه</button>
				<button class="ds-tabbar-item" type="button" data-tab="conn"><svg class="ico inline" aria-hidden="true"><use href="#i-puzzle"/></svg> اتصال و ضد DPI</button>
