						<input class="ds-input" type="text" name="username" value="${val("username", "")}" aria-required="true">
					</label>
					<div class="ds-field">
						<span class="ds-field-label">*UUID</span>
						<div class="ds-actions ds-no-wrap">
							<input type="text" name="uuid" class="ds-input is-mono mono ds-flex-1" value="${val("uuid", "") || newUuid()}" aria-required="true"${isEdit ? ' readonly title="UUID کاربرِ ساخته‌شده فقط با تاس عوض می‌شود"' : ""}>
