	/* ── ساخت سریع کاربر — میانبر یک‌کلیکی (v3.0.4) ─────────────────────
	   One click, one user with four real exits. The flow is deliberately
	   automatic and visibly so: a progress line fills while the panel fetches
	   the free list, pings candidates country by country over both protocols,
	   picks the protocol that actually produced healthy exits, and creates an
	   ordinary user with a random username. Every choice it made is written
	   into the log as it happens, so the speed never hides the reasoning.
	   The created user has «اتصال مستقیم» off (with direct on, the Worker's
	   own route wins and the locations become decoration), no clean-IP ties,
	   and the per-slot auto-replace opt-in on every location. */
	/* v3.0.6 — after the last step the progress block waits this long at 100%,
	   then fades out over QUICK_FADE_MS, and only then the result is shown. */
	const QUICK_DONE_DELAY_MS = 2000;
	const QUICK_FADE_MS = 600;
	const pause = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
	const QUICK_LOCATIONS = 4;    /* the promise: four exits */
	const QUICK_PER_COUNTRY = 4;  /* candidates pinged per country, per round */
	const QUICK_ROUNDS = 2;       /* a free list is a lottery: try the next four */
	/* v3.0.7 — only countries whose free pool holds at least this many proxies are
	   candidates. A thin country has too few exits to pick the quickest from. */
	const QUICK_MIN_PROXIES = 6;
	const QUICK_PROTOCOLS = ["socks5", "http"];
	/* Probes per test request. The API runs one request's probes side by side
	   (five at a time), so small requests that all go out together finish in about
	   the time of their slowest probe. */
	const QUICK_BATCH = 5;
	/* A test request that has not answered by then counts as silent. */
	const QUICK_TEST_TIMEOUT_MS = 30000;

	/* Country buckets of a fetched pool, most-populated first. */
	function mlCountryGroups(pool, pinned = "") {
		const groups = new Map();
		for (const entry of pool) {
			const code = String(entry?.country || "").trim().toUpperCase();
			if (!/^[A-Z]{2}$/.test(code)) continue;
			if (!groups.has(code)) groups.set(code, []);
			groups.get(code).push(entry);
		}
		return [...groups.entries()]
			.map(([code, entries]) => ({ code, entries }))
			.filter((group) => group.entries.length >= QUICK_MIN_PROXIES)
			.sort((a, b) => ((a.code === pinned ? -1 : b.code === pinned ? 1 : 0)) || (b.entries.length - a.entries.length) || a.code.localeCompare(b.code));
	}

	/* Ranking and picking are pure functions so the promise — «the protocol
	   that actually produced healthy exits wins, then the four lowest-latency
	   exits, one per country» — is testable without a browser or a network. */
	function quickRankProtocols(scores) {
		return [...(scores || [])]
			.filter((score) => score?.wins?.length)
			.sort((a, b) => (b.wins.length - a.wins.length) || (a.mean - b.mean));
	}
	function quickPickSlots(scores, limit = QUICK_LOCATIONS) {
		const ranked = quickRankProtocols(scores);
		const used = new Set();
		const chosen = [];
		const take = (wins) => {
			for (const win of [...wins].sort((a, b) => a.latency - b.latency)) {
				if (chosen.length >= limit) return;
				if (used.has(win.country)) continue;
				used.add(win.country);
				chosen.push(win);
			}
		};
		if (ranked.length) take(ranked[0].wins);
		/* Fewer healthy exits than promised on the better protocol? Top up from
		   the other one instead of quietly shipping a shorter list. */
		for (const score of ranked.slice(1)) take(score.wins);
		return { ranked, chosen };
	}

	/* A list cut into requests of at most `size` items, order kept. */
	function quickChunk(items, size) {
		const chunks = [];
		for (let offset = 0; offset < items.length; offset += size) chunks.push(items.slice(offset, offset + size));
		return chunks;
	}

	/* `user-` + five letters/digits from an unambiguous alphabet: short enough
	   to type, random enough not to collide, and never a name that looks like
	   the operator's own naming scheme. */
	function randomUsername() {
		const alphabet = "abcdefghjkmnpqrstuvwxyz23456789";
		const bytes = new Uint8Array(5);
		crypto.getRandomValues(bytes);
		return `user-${Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join("")}`;
	}

	function quickUserModal() {
		const modal = openModal({
			title: "ساخت سریع کاربر",
			size: "sm",
			center: true,
			body: `<div class="quick-build" dir="rtl">
				<div class="quick-progress">
					<div class="ds-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-label="پیشرفت ساخت"><div class="ds-progress-track"><span class="ds-progress-fill" style="--ds-progress:0"></span></div></div>
					<div class="quick-pct" aria-hidden="true">۰٪</div>
					<div class="quick-log" role="status" aria-live="polite"></div>
				</div>
			</div>`,
		});
		const bar = $(".ds-progress-fill", modal.root);
		const pct = $(".quick-pct", modal.root);
		const log = $(".quick-log", modal.root);
		const body = $(".quick-build", modal.root);

		const say = (text, kind) => {
			const line = document.createElement("div");
			line.className = `quick-line${kind ? ` ${kind}` : ""}`;
			line.innerHTML = `<span class="quick-dot" aria-hidden="true"></span><span>${esc(text)}</span>`;
			log.appendChild(line);
			/* Keep the newest line in view without stealing focus. */
			log.scrollTop = log.scrollHeight;
		};
		const step = (percent, text) => {
			const value = Math.max(0, Math.min(100, Math.round(percent)));
			bar.style.setProperty("--ds-progress", String(value / 100));
			pct.textContent = `${fa(value)}٪`;
			bar.closest("[role='progressbar']").setAttribute("aria-valuenow", String(value));
			if (text) say(text);
		};

		/* One country → one real exit: the four fastest healthy addresses of a
		   country are pinged in a round, and the winner is the quickest one. Every
		   candidate of a round goes out at once, cut into small requests of
		   QUICK_BATCH probes that the API runs side by side. A round therefore lasts
		   as long as its slowest request instead of the sum of all of them. */
		function quickBatches(plan, round) {
			return plan.groups
				.map((group) => ({ group, candidates: group.entries.slice(round * QUICK_PER_COUNTRY, (round + 1) * QUICK_PER_COUNTRY) }))
				.filter((batch) => batch.candidates.length && !batch.group.win);
		}
		function quickRequests(plan, round) {
			return quickChunk(quickBatches(plan, round).flatMap((batch) => batch.candidates.map((entry) => entry.url)), QUICK_BATCH);
		}
		function withDeadline(promise, ms) {
			let timer;
			return Promise.race([
				promise,
				new Promise((_, reject) => { timer = setTimeout(() => reject(new Error("زمان تست تمام شد")), ms); }),
			]).finally(() => clearTimeout(timer));
		}
		async function huntExit(plan, round, onRequest) {
			const batches = quickBatches(plan, round);
			const requests = quickRequests(plan, round);
			if (!requests.length) return;
			const results = new Map();
			await Promise.all(requests.map(async (proxies) => {
				try {
					const data = await withDeadline(api.post("/api/tools/test-proxy", { proxies, geo: false }), QUICK_TEST_TIMEOUT_MS);
					for (const result of data.results || []) results.set(result.proxy, result);
				} catch (error) {
					say(`یک دسته تست نشد: ${error.message || "خطای شبکه"}`, "warn");
				} finally {
					onRequest();
				}
			}));
			for (const batch of batches) {
				const best = batch.candidates
					.map((entry) => ({ entry, result: results.get(entry.url) }))
					.filter((row) => row.result?.ok)
					.sort((a, b) => (a.result.latency ?? Number.MAX_SAFE_INTEGER) - (b.result.latency ?? Number.MAX_SAFE_INTEGER))[0];
				if (!best) continue;
				batch.group.win = { protocol: plan.protocol, country: batch.group.code, entry: best.entry, latency: Math.round(best.result.latency || 0) };
			}
		}

		async function build() {
			step(4, "شروع…");
			/* ── ۱: فهرست هر دو پروتکل ─────────────────────────────────── */
			step(8, `واکشی فهرست رایگان برای ${fa(QUICK_PROTOCOLS.length)} پروتکل…`);
			const plans = await Promise.all(QUICK_PROTOCOLS.map(async (protocol) => {
				try {
					/* `country: ""` is deliberate — the settings default would pin
					   the whole thing to one country. */
					const data = await api.post("/api/tools/public-proxies", { protocol, limit: 500, country: "" });
					const list = (data.proxies || []).filter((entry) => String(entry?.country || "").trim());
					if (!list.length) say(`${protocol}: فهرست خالی برگشت${data.errors?.length ? ` (${data.errors[0]?.error || "خطای شبکه"})` : ""}.`, "warn");
					return { protocol, list, groups: mlCountryGroups(list) };
				} catch (error) {
					say(`${protocol}: واکشی نشد — ${error.message || "خطای نامشخص"}.`, "warn");
					return { protocol, list: [], groups: [] };
				}
			}));
			const live = plans.filter((plan) => plan.groups.length);
			if (!live.length) throw new Error(`هیچ کشوری در فهرست رایگان به ${fa(QUICK_MIN_PROXIES)} پروکسی نرسید؛ یک بار دیگر تلاش کنید.`);
			for (const plan of live) say(`${plan.protocol}: ${fa(plan.list.length)} کاندید در ${fa(plan.groups.length)} کشور.`);
			step(24);

			/* ── ۲: پینگ کاندیدها — هر دور، همه‌ی پروتکل‌ها هم‌زمان ───────── */
			let round = 0;
			let planned = 0;
			let answered = 0;
			/* The bar follows finished requests, so it moves while the probes run. */
			const progress = () => step(26 + ((round + (planned ? answered / planned : 1)) / QUICK_ROUNDS) * 48);
			const answer = () => { answered++; progress(); };
			const winsNow = () => live.reduce((sum, plan) => sum + plan.groups.filter((group) => group.win).length, 0);
			step(26, "پینگ کاندیدها — هر کشور چهار کاندید در هر دور…");
			for (round = 0; round < QUICK_ROUNDS; round++) {
				planned = live.reduce((sum, plan) => sum + quickRequests(plan, round).length, 0);
				answered = 0;
				if (!planned) continue;
				const before = winsNow();
				say(`دور ${fa(round + 1)}: ${fa(planned)} درخواست تست، همه با هم…`);
				await Promise.all(live.map((plan) => huntExit(plan, round, answer)));
				say(`دور ${fa(round + 1)} تمام شد: ${fa(winsNow() - before)} خروج سالم پیدا شد.`, "ok");
			}

			/* ── ۳: بهترین پروتکل ──────────────────────────────────────── */
			const scores = live.map((plan) => {
				const wins = plan.groups.map((group) => group.win).filter(Boolean);
				const mean = wins.length ? wins.reduce((sum, win) => sum + win.latency, 0) / wins.length : Number.MAX_SAFE_INTEGER;
				return { protocol: plan.protocol, wins, mean };
			});
			const { ranked, chosen } = quickPickSlots(scores);
			const best = ranked[0];
			for (const score of ranked) {
				if (score.protocol !== best.protocol) say(`${score.protocol}: ${fa(score.wins.length)} خروج سالم.`);
			}
			step(76, `بهترین پروتکل: ${best.protocol} — ${fa(best.wins.length)} خروج سالم${best.wins.length ? ` (میانگین ${fa(Math.round(best.mean))} میلی‌ثانیه)` : ""}.`);

			/* ── ۴: چهار خروج کم‌پینگ ─────────────────────────────────── */
			if (chosen.length < QUICK_LOCATIONS && ranked.length > 1) {
				say(`برای رسیدن به ${fa(QUICK_LOCATIONS)} لوکیشن از پروتکل دیگر هم برداشته می‌شود…`, "warn");
			}
			const slots = chosen
				.slice()
				.sort((a, b) => a.latency - b.latency)
				.map((win) => {
					say(`${countryLabel({ country: win.country, country_name: win.entry.country_name })}: ${win.protocol} · ${fa(win.latency)} میلی‌ثانیه ✓`, "ok");
					return { proxy: win.entry.url, country: win.country, country_name: win.entry.country_name || null, source: "public", auto_replace: true };
				});
			if (slots.length < 2) throw new Error("خروج سالم کافی پیدا نشد؛ یک بار دیگر بزنید — فهرست رایگان هر ساعت عوض می‌شود.");

			/* ── ۵: ساخت کاربر ────────────────────────────────────────── */
			step(84, "ساخت کاربر…");
			let created = null;
			let username = randomUsername();
			for (let attempt = 0; attempt < 4 && !created; attempt++) {
				try {
					created = await api.post("/api/users", {
						username,
						is_active: 1,
						/* Off on purpose: with direct on, the Worker's own route
						   wins and every location below becomes decoration. */
						enable_direct: 0,
						ips: null,
						ip_operator: "manual",
						ip_pool: null,
						ip_count: 0,
						rotate_time: 0,
						auto_rotate_ip: 0,
						user_socks5: JSON.stringify(slots),
						auto_rotate_user_proxy: 0,
					});
				} catch (error) {
					/* The random name is short: a collision is possible, and the
					   server is the one that knows. Roll again instead of failing. */
					if (!/ثبت شده/.test(String(error?.message || ""))) throw error;
					say(`نام «${username}» تکراری بود — نام تازه گرفته شد.`, "warn");
					username = randomUsername();
				}
			}
			if (!created) throw new Error("ساخت کاربر بعد از چند تلاش نام‌گذاری نشد.");
			step(100);
			say(`کاربر «${created.user.username}» با ${fa(slots.length)} خروج واقعی ساخته شد.`, "ok");
			await showResult(() => finish(created.user.username, slots.length));
			await Promise.all([loadUsers(), loadOverview()]);
			if (state.page === "users" || state.page === "dashboard") render();
		}

		/* v3.0.7 — the bar and the log stay for QUICK_DONE_DELAY_MS at 100% (or at the
		   point a failure happened), fade out on their own, and only then the result
		   view replaces them. The result never sits underneath the progress. */
		async function showResult(render) {
			await pause(QUICK_DONE_DELAY_MS);
			const fading = $(".quick-progress", modal.root);
			if (fading) fading.classList.add("is-leaving");
			await pause(QUICK_FADE_MS);
			if (fading) fading.hidden = true;
			render();
		}

		function finish(username, count) {
			const done = document.createElement("div");
			done.className = "quick-done";
			done.dir = "rtl";
			done.innerHTML = `
				<div class="quick-done-icon" aria-hidden="true">✓</div>
				<h4 class="quick-done-title">کاربر جدید با موفقیت ساخته شد</h4>
				<p class="quick-done-note"><span class="quick-done-tag">توجه</span><span class="quick-done-note-text">برای اتصال بهتر آیپی تمیز در کاربر قرار دهید</span><span class="quick-done-tag">توجه</span></p>
				<p class="quick-done-meta">نام کاربری: <b dir="ltr">${esc(username)}</b> · ${fa(count)} لوکیشن</p>
				<div class="quick-done-actions">
					<button class="ds-btn is-primary" id="quick-goto-ips">${icon("globe")}<span>ورود به بخش آیپی تمیز</span></button>
					<button class="ds-btn is-ghost" data-close>بستن</button>
				</div>`;
			body.appendChild(done);
			$("#quick-goto-ips", done).addEventListener("click", () => {
				modal.close();
				go("ips");
			});
		}

		/* v3.0.7 — a failure gets the same treatment as a success: the progress fades
		   out and the failure is shown as its own view, not underneath the bar. */
		build().catch((error) => showResult(() => {
			const failed = document.createElement("div");
			failed.className = "quick-done error";
			failed.dir = "rtl";
			failed.innerHTML = `
				<div class="quick-done-icon" aria-hidden="true">!</div>
				<h4 class="quick-done-title">ساخت کاربر انجام نشد</h4>
				<p class="quick-done-hint">${esc(error.message || "خطای نامشخص")}</p>
				<div class="quick-done-actions">
					<button class="ds-btn" id="quick-retry">تلاش دوباره</button>
					<button class="ds-btn is-ghost" data-close>بستن</button>
				</div>`;
			body.appendChild(failed);
			$("#quick-retry", failed).addEventListener("click", () => {
				modal.close();
				quickUserModal();
			});
		}));
	}

	function uuidFallback() {
		const bytes = new Uint8Array(16);
		crypto.getRandomValues(bytes);
		bytes[6] = (bytes[6] & 0x0f) | 0x40;
		bytes[8] = (bytes[8] & 0x3f) | 0x80;
		const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
		return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
	}

	/** One proxy per line → JSON array (multi-location mode). */
	function normalizeProxyField(value) {
		const text = String(value || "").trim();
		if (!text) return null;
		if (text.startsWith("[")) return text;
		const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
		if (lines.length <= 1) return lines[0] || null;
		return JSON.stringify(lines.map((proxy) => ({ proxy, country: null })));
	}

	/* ── links / QR modal ─────────────────────────────────────────────── */
	/* v2.3.12 — QR for the links modal: the same qrcode-generator global the
	   status page uses (the QR script is inlined in panel.html as well), the same
	   .qr-box look and the same fixed-size SVG that v2.3.11 taught it to paint.
	   Toggle behaviour mirrors the status page: the same button collapses. */
	function renderQrTo(area, text) {
		area.innerHTML = "";
		const qrLib = (typeof qrcode === "function" ? qrcode : (typeof window !== "undefined" && typeof window.qrcode === "function" ? window.qrcode : null));
		if (!qrLib) {
			area.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">کتابخانه QR در دسترس نیست.</div>';
			return;
		}
		try {
			let qr;
			try {
				qr = qrLib(0, "M");
				if (qrLib.stringToBytesFuncs && qrLib.stringToBytesFuncs["UTF-8"]) {
					const prev = qrLib.stringToBytes;
					qrLib.stringToBytes = qrLib.stringToBytesFuncs["UTF-8"];
					qr.addData(text);
					qrLib.stringToBytes = prev;
				} else qr.addData(text);
				qr.make();
			} catch {
				qr = qrLib(0, "L");
				qr.addData(text); qr.make();
			}
			const box = document.createElement("div");
			box.className = "qr-box";
			box.innerHTML = qr.createSvgTag({ cellSize: 5, margin: 2, scalable: true });
			area.appendChild(box);
			const cap = document.createElement("div");
			cap.className = "qr-caption";
			cap.textContent = text.length > 90 ? text.slice(0, 90) + "…" : text;
			area.appendChild(cap);
		} catch (error) {
			area.innerHTML = `<div class="ds-banner ds-tone-danger is-inline">${esc(error.message)}</div>`;
		}
	}

