				<div class="link-row"><span class="dim ds-caption ds-link-label">وضعیت:</span><span class="txt" title="${esc(data.status_url)}">${esc(data.status_url)}</span><button class="ds-btn is-sm is-icon" data-copy="${esc(data.status_url)}" aria-label="کپی"><svg class="ico" aria-hidden="true"><use href="#i-copy"/></svg></button><a class="ds-btn is-sm is-icon" href="${esc(data.status_url)}" target="_blank" rel="noopener" aria-label="باز کردن"><svg class="ico" aria-hidden="true"><use href="#i-external"/></svg></a></div>
