				<div class="ds-banner ds-tone-info is-inline ds-mt-3 links-note">این نشانی‌ها <b>اختصاصی همین کاربر</b> هستند: یک نشانه‌ی تصادفی در آدرس می‌نشیند، نه نام کاربری. هر کس نشانی را داشته باشد کانفیگ را هم دارد — اگر جایی لو رفت، «لینک جدید» بسازید تا نشانی‌های قبلی بی‌درنگ از کار بیفتند.</div>
				<div class="ds-actions links-actions"><button class="ds-btn is-sm" id="copy-all-links"><svg class="ico" aria-hidden="true"><use href="#i-copy"/></svg><span>کپی همه‌ی کانفیگ‌ها</span></button><button class="ds-btn is-sm" id="copy-sub-link">📋 کپی لینک ساب</button><button class="ds-btn is-sm" id="copy-status-link">📈 کپی لینک وضعیت</button><button class="ds-btn is-sm is-danger" id="rotate-links">🔁 لینک جدید</button></div>
`,
		});

		modal.root.addEventListener("click", (event) => {
			const copyTarget = event.target.closest("[data-copy]");
			if (copyTarget) copyText(copyTarget.dataset.copy);
			const qrTarget = event.target.closest("[data-qr-btn]");
			if (qrTarget) openQrWindow(qrTarget.dataset.qrText || "");
