		$("#copy-sub-link", modal.root).addEventListener("click", () => copyText(data.sub_url, "لینک اشتراک"));
		$("#copy-status-link", modal.root).addEventListener("click", () => copyText(data.status_url, "لینک وضعیت"));
		$("#rotate-links", modal.root).addEventListener("click", () => {
			modal.close();
			return rotateUserLinks(username, { reopenLinks: true });
		});
	}

	/* ── proxy test rendering ─────────────────────────────────────────── */
	/* Persian failure text for bare-IP (ProxyIP) results — the two honest
	   verdicts of the CF relay probe — English errors for everything else. */
	function proxyTestFailText(result) {
		if (result?.protocol === "proxyip" && result?.tcp_ok) {
			return result.fail === "not-cf" ? "پاسخ می‌دهد ولی رله‌ی Cloudflare نیست" : "فقط TCP — رله نمی‌کند";
		}
		return result?.error || "خطا";
	}

	/* v3.0.1 — the type column says what the connector actually does: `https://`
	   is accepted and treated exactly like `http://` (CONNECT over a plain TCP
	   socket to the proxy). The old wording implied TLS all the way to the
	   proxy, which the connector never did. */
	const PROXY_TYPE_NOTE = "پروتکل‌های http و https هر دو با CONNECT روی یک اتصال معمولی به پروکسی فرستاده می‌شوند؛ TLS فقط تا مقصد برقرار می‌شود.";

	function renderProxyResults(results, message) {
		if (message) return `<div class="ds-banner ds-tone-info is-inline">${esc(message)}</div>`;
		if (!results.length) return '<div class="ds-empty is-compact is-flat"><p class="ds-empty-text">نتیجه‌ای نیست.</p></div>';
		return `<div class="ds-table-wrap"><table class="ds-table is-panel" aria-label="جدول داده‌ها"><thead><tr><th scope="col">پروکسی</th><th scope="col">نوع</th><th scope="col">کشور</th><th scope="col">وضعیت</th><th scope="col">IP خروجی</th><th scope="col">تأخیر</th></tr></thead><tbody>${results
			.map(
				(result) => `<tr>
					<td class="mono ds-proxy-cell">${esc(result.proxy)}</td>
					<td><span class="ds-badge ds-tone-info">${esc(result.protocol || "?")}</span></td>
					<td class="nowrap">${result.geo?.country ? `${flagMarkup(result.geo.country)} ${esc(result.geo.country)}` : "—"}</td>
					<td>${result.ok ? (result.test === "relay" ? '<span class="ds-badge ds-tone-success">سالم · رله</span>' : '<span class="ds-badge ds-tone-success">سالم</span>') : `<span class="ds-badge ds-tone-danger">${esc(proxyTestFailText(result))}</span>`}</td>
					<td class="mono">${esc(result.ip || "—")}</td>
					<td class="nowrap">${fa(num(result.latency, 0))} ms</td>
				</tr>`
			)
			.join("")}</tbody></table></div><div class="dim ds-caption ds-mt-2">${PROXY_TYPE_NOTE}</div>`;
	}

	/* ── page rendering & wiring ──────────────────────────────────────── */
	/* v2.3.14 — ownership lock: when the integrity chain over the panel's
	   identity (title, brand, watermark lines, channel, stream path) breaks,
	   every admin page opens with this red banner. The streams are already
	   being refused server-side; this explains it to the operator. */
	function integrityBanner() {
		const integrity = state.integrity;
		if (!integrity || integrity.ok) return "";
		const names = {
			panel_title: "عنوان پنل",
			brand_name: "نام برند",
			brand_line1: "خط اول واترمارک",
			brand_line2: "خط دوم واترمارک",
			brand_channel: "لینک کانال",
			stream_path: "مسیر استریم",
		};
		const list = (integrity.mismatched || []).map((key) => names[key] || key).join("، ");
		return `<div class="ds-banner ds-tone-danger lines is-inline ds-border-strong" role="alert">
⚠️ <b>قفل مالکیت فعال شده — اتصال‌های VLESS/Trojan قطع هستند.</b>
هویت این پنل با نسخه‌ی رسمی Bee.Hive Panel مغایرت دارد${list ? `: ${esc(list)}` : ""}.
تا زمان بازگشت این مقادیر به حالت اصلی، کانفیگ‌ها کار نمی‌کنند و هیچ اتصالی پذیرفته نمی‌شود؛ خود پنل سالم است.
این پنل با لایسنسِ «بدون ریبرند» منتشر شده (LICENSE و AGENTS.md): تغییر عنوان، تبلیغات یا مسیر استریم مجاز نیست.
برای رفع: پشتیبان یا متغیرهایی که این مقادیر را عوض کرده‌اند را حذف کنید و مقادیر را به پیش‌فرض برگردانید.
</div>`;
	}

	/* The banner lives in its own container above every page (#lock-banner in
	   panel.html) so it survives page renders and updates whenever settings
	   reload — including right after a save. */
	function paintLockBanner() {
		const box = document.getElementById("lock-banner");
		if (!box) return;
		const markup = integrityBanner();
		box.hidden = !markup;
		box.innerHTML = markup;
	}

	function renderExternalConfigs() {
		return `
		<div class="ds-stack">
			<div class="ds-card">
				<h2 class="ds-card-title">External Raw Configs</h2>
				<p class="dim">You can add personal subscriptions and direct URL configs here. Bee.Hive fetches supported public HTTPS subscriptions and aggregates the discovered links below. One entry per line.</p>
				<label class="ds-field"><span class="ds-field-label">Subscription URLs or config links</span><textarea id="external-config-sources" class="ds-input" rows="8" dir="ltr" placeholder="https://example.com/subscription&#10;vless://…&#10;vmess://…"></textarea><span class="ds-field-help">Allowed: public HTTPS subscription URLs and VLESS, VMess, Trojan, Shadowsocks, Hysteria2, TUIC, SOCKS, or HTTP config links. Private/local URLs are rejected.</span></label>
				<div class="ds-actions ds-mt-3"><button type="button" class="ds-btn is-primary" id="external-config-save">Save sources</button><button type="button" class="ds-btn" id="external-config-fetch">Fetch &amp; aggregate</button><button type="button" class="ds-btn" id="external-config-copy" disabled>Copy all configs</button><span id="external-config-status" class="dim" role="status"></span></div>
			</div>
			<div class="ds-card"><div class="ds-row"><h3 class="ds-card-title ds-flex-1">Aggregated configs</h3><span id="external-config-count" class="ds-badge">0</span></div><div id="external-config-results" class="ds-stack"><div class="ds-empty is-flat">Save source URLs, then choose Fetch &amp; aggregate.</div></div><div id="external-config-errors" class="ds-stack"></div></div>
		</div>`;
	}

	function render() {
		const host = $(`#page-${state.page}`);
		if (!host) return;
		if (state.page === "dashboard") host.innerHTML = renderDashboard();
		else if (state.page === "users") host.innerHTML = renderUsers();
		else if (state.page === "ips") host.innerHTML = renderIps();
		else if (state.page === "tools") host.innerHTML = renderTools();
		else if (state.page === "settings") host.innerHTML = renderSettings();
		else if (state.page === "external-configs") host.innerHTML = renderExternalConfigs();
		else if (state.page === "backup") host.innerHTML = renderBackup();
		else if (state.page === "help") host.innerHTML = renderHelp();
		wire(host);
		window.DevCopUI.enhance(host);
	}

	function wire(host) {
		if (state.page === "external-configs") wireExternalConfigs(host);

		/* Cloudflare requests total reset — dashboard */
		const resetUsageBtn = $("#btn-reset-usage", host);
		if (resetUsageBtn) {
			resetUsageBtn.addEventListener("click", async () => {
				if (!(await confirmDialog("حجم مصرفی دوره‌ی جاری همه‌ی کاربران صفر شود؟ «مجموعاً» دست‌نخورده می‌ماند.", { confirmText: "ریست کن" }))) return;
				try {
					const data = await api.post("/api/system/reset-usage", {});
					await Promise.all([loadUsers(), loadOverview()]);
					render();
					toast(`حجم دوره ریست شد — ${fa(num(data.reset_users || 0))} کاربر ✅`, "ok");
				} catch (error) {
					toast(error.message, "err");
				}
			});
		}
		const resetTotalBtn = $("#btn-reset-requests-total", host);
		if (resetTotalBtn) {
			resetTotalBtn.addEventListener("click", async () => {
				if (!(await confirmDialog("شمارش کل درخواست‌ها صفر شود؟ (شروع دوباره از صفر)", { confirmText: "ریست کن" }))) return;
				try {
					await api.post("/api/system/reset-requests", { scope: "total" });
					await loadOverview();
					render();
					toast("شمارش کل ریست شد \u2705", "ok");
				} catch (e) { toast(e.message, "err"); }
			});
		}
		/* global action buttons */
		$$("[data-act]", host).forEach((button) => {
			button.addEventListener("click", () => runAction(button.dataset.act));
		});

		if (state.page === "users" || state.page === "dashboard") {
			const search = $("#user-search", host);
			if (search) {
				search.addEventListener("input", debounce(async (event) => {
					state.search = event.target.value;
					await loadUsers();
					render();
					const again = $("#user-search");
					if (again) {
						again.focus();
						again.setSelectionRange(again.value.length, again.value.length);
					}
				}, 350));
			}
			const order = $("#user-order", host);
			if (order) {
				order.addEventListener("change", async (event) => {
					state.order = event.target.value;
					await loadUsers();
					render();
				});
			}
			const checkAll = $("#check-all", host);
			if (checkAll) {
				checkAll.checked = state.users.length > 0 && state.selected.size === state.users.length;
				checkAll.indeterminate = state.selected.size > 0 && state.selected.size < state.users.length;
				checkAll.addEventListener("change", (event) => {
					if (event.target.checked) state.users.forEach((user) => state.selected.add(user.username));
					else state.selected.clear();
					render();
				});
			}
			$$("[data-check]", host).forEach((box) => {
				box.addEventListener("change", (event) => {
					const name = event.target.dataset.check;
					if (event.target.checked) state.selected.add(name);
					else state.selected.delete(name);
					const bar = $("#bulk-bar");
					if (bar) bar.hidden = !state.selected.size;
					const counter = $("#bulk-bar .ds-badge");
					if (counter) counter.textContent = `${fa(state.selected.size)} انتخاب شده`;
					event.target.closest("tr").classList.toggle("is-selected", event.target.checked);
					if (checkAll) { checkAll.checked = state.selected.size === state.users.length; checkAll.indeterminate = state.selected.size > 0 && state.selected.size < state.users.length; }
				});
			});
			const clearBulk = $("#bulk-clear", host);
			if (clearBulk) clearBulk.addEventListener("click", () => { state.selected.clear(); render(); });
			$$("[data-bulk]", host).forEach((button) => button.addEventListener("click", () => runBulk(button.dataset.bulk)));
			const exportUsers = $("#btn-export-users", host);
			if (exportUsers) exportUsers.addEventListener("click", () => downloadJson(state.users, "devcop-users.json"));

			$$("tbody tr[data-user]", host).forEach((row) => {
				const username = row.dataset.user;
				$$("[data-row]", row).forEach((button) => {
					button.addEventListener("click", () => rowAction(button.dataset.row, username));
				});
			});
		}

		if (state.page === "ips") wireIps(host);
		if (state.page === "tools") wireTools(host);
		if (state.page === "settings") wireSettings(host);
		if (state.page === "backup") wireBackup(host);
	}

	function debounce(fn, ms) {
		let timer;
		return function (...args) {
			clearTimeout(timer);
			timer = setTimeout(() => fn.apply(this, args), ms);
		};
	}

	function downloadJson(data, filename) {
		const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
		const url = URL.createObjectURL(blob);
		const anchor = document.createElement("a");
		anchor.href = url;
		anchor.download = filename;
		anchor.click();
		setTimeout(() => URL.revokeObjectURL(url), 1500);
	}

	/* ── row / bulk actions ───────────────────────────────────────────── */
	/**
	 * v3.0.1 — mints a new public link for a user.
	 *
	 * Every subscription and status URL is built from a per-user random token,
	 * so this is the one action that "recalls" a leaked link: the old token stops
	 * resolving immediately (404 on the subscription routes, the notice page on
	 * /status) while the account, its UUID, its usage and its quota stay exactly
	 * as they were. Nothing on the user's device changes until they import the
	 * new link, which is why the dialog says so in plain words.
	 */
	async function rotateUserLinks(username, { reopenLinks = false } = {}) {
		if (!(await confirmDialog(`لینک‌های فعلی «${username}» باطل می‌شوند و یک لینک تازه ساخته می‌شود. کاربر باید لینک تازه را در برنامه‌اش وارد کند؛ نشانی‌های قبلی دیگر کار نمی‌کنند. ادامه؟`, { title: "ساخت لینک جدید", confirmText: "لینک تازه بساز" }))) return;
		try {
			await api.post(`/api/users/${encodeURIComponent(username)}/rotate-links`);
			toast("لینک تازه ساخته شد؛ لینک‌های قبلی دیگر کار نمی‌کنند.", "ok");
			await loadUsers();
			render();
			if (reopenLinks) return linksModal(username);
		} catch (error) {
			toast(error.message, "err");
		}
	}

	async function rowAction(action, username) {
		const user = state.users.find((entry) => entry.username === username);
		if (action === "edit") return userFormModal(user);
		if (action === "links") return linksModal(username);
		if (action === "status") {
			/* v3.0.1 — the status page lives behind the user's random token, so the
			   URL comes from the API payload and never from the username. */
			const target = user && user.status_url;
			if (!target) return toast("نشانی وضعیت این کاربر آماده نیست؛ فهرست کاربران را بروزرسانی کنید.", "err");
			return window.open(target, "_blank", "noopener");
		}
		if (action === "rotate-links") return rotateUserLinks(username);
		if (action === "toggle") {
			try {
				await api.post(`/api/users/${encodeURIComponent(username)}/toggle`);
				toast("وضعیت کاربر تغییر کرد.", "ok");
				await loadUsers();
				render();
			} catch (error) {
				toast(error.message, "err");
			}
			return;
		}
		if (action === "reset") {
			if (!(await confirmDialog(`سهمیه و زمان کاربر «${username}» ریست شود؟`, { confirmText: "ریست کن" }))) return;
			try {
				await api.post(`/api/users/${encodeURIComponent(username)}/reset`, { scope: "all" });
				toast("ریست انجام شد.", "ok");
				await loadUsers();
				render();
			} catch (error) {
				toast(error.message, "err");
			}
			return;
		}
		if (action === "delete") {
			if (!(await confirmDialog(`کاربر «${username}» برای همیشه حذف شود؟`, { confirmText: "حذف کن" }))) return;
			try {
				await api.del(`/api/users/${encodeURIComponent(username)}`);
				state.selected.delete(username);
				toast("کاربر حذف شد.", "ok");
				await loadUsers();
				await loadOverview();
				render();
			} catch (error) {
				toast(error.message, "err");
			}
		}
	}

	async function runBulk(action) {
		const usernames = [...state.selected];
		if (!usernames.length) return toast("هیچ کاربری انتخاب نشده است.", "warn");
		let payload = { usernames, action };

		if (action === "delete") {
			if (!(await confirmDialog(`${fa(usernames.length)} کاربر حذف شوند؟ این عمل بازگشت‌پذیر نیست.`, { confirmText: "حذف کن" }))) return;
		}
		if (action === "extend_days") {
			const days = await numberDialog("چند روز اضافه شود؟", 30);
			if (!days) return;
			payload.days = Number(days);
		}
		if (action === "add_volume") {
			const volume = await numberDialog("چند گیگابایت اضافه شود؟", 10);
			if (!volume) return;
			payload.gb = Number(volume);
		}

		try {
			const result = await api.post("/api/users/bulk", payload);
			toast(`عملیات روی ${fa(result.affected)} کاربر اعمال شد ✅`, "ok");
			state.selected.clear();
			await Promise.all([loadUsers(), loadOverview()]);
			render();
		} catch (error) {
			toast(error.message, "err");
		}
	}

	async function runAction(action) {
		try {
			if (action === "add-user") return userFormModal(null);
			if (action === "add-quick-user") return quickUserModal();
			if (action === "run-jobs") {
				const result = await api.post("/api/system/run-jobs");
				toast(`ریست: ${fa(result.resets)} · چرخش IP: ${fa(result.rotated)} · انقضا: ${fa(result.expired)}`, "ok");
				await Promise.all([loadUsers(), loadOverview()]);
				return render();
			}
			if (action === "flush") {
				const result = await api.post("/api/system/flush");
				toast(`آمار ${fa(result.flushed_users)} کاربر ثبت شد.`, "ok");
				await Promise.all([loadUsers(), loadOverview()]);
				return render();
			}
			if (action === "flush-dns" || action === "reload-blocklist") {
				await api.post("/api/flush-cache");
				toast("کش‌ها پاک و لیست‌ها تازه شدند.", "ok");
				return render();
			}
		} catch (error) {
			toast(error.message, "err");
		}
	}

	/* ── page-specific wiring ─────────────────────────────────────────── */
	function wireIps(host) {
		/* ── named pools: render (settings-style collapse), copy, delete ── */
		renderPoolsInto(host);
		$("#pools-list", host).addEventListener("click", async (event) => {
			const rescan = event.target.closest("[data-pool-rescan]");
			if (rescan) {
				const name = rescan.closest(".pool-item")?.dataset.poolName;
				if (name) rescanPoolModal(name);
				return;
			}
			const del = event.target.closest("[data-pool-del]");
			if (del) {
				const item = del.closest(".pool-item");
				const name = item?.dataset.poolName;
				if (!name) return;
				if (!(await confirmDialog(`استخر «${esc(name)}» و همه‌ی آیپی‌های آن حذف شود؟`, { confirmText: "حذف استخر" }))) return;
				try {
					await api.del(`/api/ip-pools/${encodeURIComponent(name)}`);
					await loadPools();
					renderPoolsInto(host);
					toast(`استخر «${esc(name)}» حذف شد.`, "ok");
				} catch (error) {
					toast(error.message, "err");
				}
				return;
			}
			const copy = event.target.closest("[data-pool-copy]");
			if (copy) {
				const block = $(".code-block", copy.closest(".pool-item"));
				if (block) copyText(block.textContent, "آیپی‌های استخر");
			}
		});

		/* ── import a public pool from a URL — server-side fetch, «استخر عمومی» suffix ── */
		$("#pool-url-add", host).addEventListener("click", async () => {
			const name = $("#pool-url-name", host).value.trim();
			const url = $("#pool-url-input", host).value.trim();
			if (!name) return toast("نام استخر را وارد کنید.", "warn");
			if (!/^https?:\/\//.test(url)) return toast("آدرس باید با http:// یا https:// شروع شود.", "warn");
			const button = $("#pool-url-add", host);
			button.disabled = true;
			try {
				const data = await api.post("/api/ip-pools", { name, url });
				$("#pool-url-name", host).value = "";
				$("#pool-url-input", host).value = "";
				await loadPools();
				renderPoolsInto(host);
				toast(`استخر «${esc(data.pool.name)}» با ${fa(data.pool.ips.length)} آیپی اضافه شد ✅`, "ok");
			} catch (error) {
				toast(error.message, "err");
			} finally {
				button.disabled = false;
			}
		});

		/* ── scanner: presets, start / pause⇄resume / finish, selection, saves ── */
		$("#scan-preset-cf", host).addEventListener("click", () => {
			$("#scan-ranges", host).value = CF_V4_RANGES.join("\n");
			toast(`${fa(CF_V4_RANGES.length)} رنج رسمی IPv4 کلودفلر در کادر ریخته شد.`, "ok");
		});
		$("#scan-box-clear", host).addEventListener("click", () => {
			$("#scan-ranges", host).value = "";
		});
		$("#scan-start", host).addEventListener("click", () => startScan());
		$("#scan-pause", host).addEventListener("click", () => {
			if (!state.scan) return;
			if (state.scan.phase === "paused") resumeScan();
			else pauseScan();
		});
		$("#scan-end", host).addEventListener("click", () => finishScan(false));
		$("#scan-top5", host).addEventListener("click", () => selectTopScan(5));
		$("#scan-top10", host).addEventListener("click", () => selectTopScan(10));
		$("#scan-top100", host).addEventListener("click", () => selectTopScan(100));
		$("#scan-none", host).addEventListener("click", () => {
			if (state.scan) { state.scan.selected = new Set(); renderScanTick(true); }
		});
		$("#scan-clear", host).addEventListener("click", () => {
			state.scan = null; /* workers see the swap and stop on their own */
			renderScanTick(true);
		});
		/* Checkboxes re-render on every tick, so selection is delegated. */
		$("#scan-results", host).addEventListener("change", (event) => {
			if (!event.target.classList.contains("scan-check")) return;
			const ip = event.target.closest(".scan-row")?.dataset.ip;
			if (!ip || !state.scan) return;
			if (event.target.checked) state.scan.selected.add(ip);
			else state.scan.selected.delete(ip);
		});

		const selectedIps = () => {
			const scan = state.scan;
			if (!scan?.selected.size) { toast("اول آیپی‌های سالم را تیک بزنید (یا «۵/۱۰ مورد برتر»).", "warn"); return null; }
			return [...scan.selected];
		};
		$("#scan-save-user", host).addEventListener("click", async () => {
			const username = $("#scan-user", host).value;
			if (!username) return toast("کاربرِ مقصد را انتخاب کنید.", "warn");
			const ips = selectedIps();
			if (!ips) return;
			try {
				const data = await api.get(`/api/users/${encodeURIComponent(username)}`);
				const existing = String(data.user?.ips || "").split(/[\n,;]/).map((ip) => ip.trim()).filter(Boolean);
				const merged = [...new Set([...existing, ...ips])];
				/* v2.3.3: saving hand-picked scan IPs into a user also switches that
				   user to «آیپی‌های دستی» — those IPs ARE the user's clean list now,
				   and pool rotation must never overwrite them. */
				await api.put(`/api/users/${encodeURIComponent(username)}`, { ips: merged.join("\n"), ip_operator: "manual", ip_pool: null });
				toast(`${fa(ips.length)} آیپی به «${esc(username)}» اضافه شد (مجموع ${fa(merged.length)}) و اپراتور استخر به «آیپی‌های دستی» تغییر کرد.`, "ok");
				/* v2.3.10 — the edit modal renders from state.users, so the scan
				   MUST refresh that cache or the freshly saved IPs stay invisible
				   in «ویرایش کاربر» until the operator reloads the page (the
				   users list is only re-fetched on page load, on list actions,
				   and by the 1–5-minute poller — none of which runs while the
				   scanner page is open). The refresh is silent on purpose: no
				   re-render, so a scan still in progress and the user select —
				   still pointing at this very user for consecutive adds — are
				   left untouched. */
				try { await loadUsers(); } catch { /* cache stays as-is; the poll or the next reload catches up */ }
			} catch (error) {
				toast(error.message, "err");
			}
		});
		$("#scan-save-pool", host).addEventListener("click", async () => {
			const name = $("#scan-pool-name", host).value.trim();
			if (!name) return toast("نام استخر را وارد کنید.", "warn");
			const ips = selectedIps();
			if (!ips) return;
			try {
				await api.post("/api/ip-pools", { name, ips });
				$("#scan-pool-name", host).value = "";
				await loadPools();
				renderPoolsInto(host);
				toast(`استخر «${esc(name)}» با ${fa(ips.length)} آیپی ذخیره شد ✅`, "ok");
			} catch (error) {
				toast(error.message, "err");
			}
		});

		/* A scan that ran (or is still running/paused) before this re-render
		   keeps its state — repaint results, counters and button states. */
		renderScanTick(true);
	}

	function wireTools(host) {
		/* v2.3.11 — the collapsible «آموزش» block folds exactly like a settings
		   card: every tools visit starts folded, one click opens it. The proxy
		   card moved out (the user modal covers it); the DNS card was retired. */
		wireCollapsibleCards(host);

		$("#ping-worker", host).addEventListener("click", async () => {
			const out = $("#ping-worker-out", host);
			out.textContent = "در حال اندازه‌گیری…";
			try {
				const data = await api.post("/api/tools/ping", { target: "https://www.gstatic.com/generate_204", count: 5 });
				out.textContent = data.avg_ms === null ? "❌ شکست" : `✅ میانگین ${fa(data.avg_ms)} ms · کمینه ${fa(data.min_ms)} · بیشینه ${fa(data.max_ms)} · افت ${fa(data.loss)}٪`;
			} catch (error) {
				out.textContent = error.message;
			}
		});

		/* Route-debug verdicts in Persian; every row says WHICH hop failed. */
		const routeVerdictText = (probe) => {
			if (!probe) return {cls: "dim", text: "آزمایش نشد"};
			if (probe.verdict === "cf") return {cls: "ok", text: `پاسخ Cloudflare (400+cf-ray) · ${fa(probe.ms)} ms`};
			if (probe.verdict === "http") return {cls: "ok", text: `پاسخ HTTP · ${fa(probe.ms)} ms · ${esc(probe.status || "")}`};
			if (probe.verdict === "silent") return {cls: "danger", text: `TCP باز است ولی پاسخی نمی‌آید · ${fa(probe.ms)} ms`};
			if (probe.verdict === "refused") return {cls: "danger", text: `اتصال رد/ناموفق · ${esc(probe.error || "")}`};
			if (probe.verdict === "write-failed") return {cls: "danger", text: `نوشتن درخواست شکست خورد · ${esc(probe.error || "")}`};
			return {cls: "danger", text: esc(probe.error || JSON.stringify(probe).slice(0, 60))};
		};
		$("#route-debug-run", host).addEventListener("click", async () => {
			const out = $("#route-debug-out", host);
			const ver = $("#route-debug-ver", host);
			const proxy = $("#route-debug-proxy", host).value.trim();
			out.innerHTML = '<span class="ds-spinner" aria-hidden="true"></span> در حال تست مسیریابی…';
			ver.textContent = "";
			try {
				const data = await api.post("/api/tools/route-debug", { proxy: proxy || null });
				ver.textContent = `نسخه‌ی پنل: ${fa(data.version || "?")}`;
				const rows = [];
				rows.push(`<tr><td>DoH (حل دامنه)</td><td>${data.doh?.ok ? `<span class="ds-badge ds-tone-success">✓ ${esc((data.doh.answers || []).join(" , "))}</span>` : '<span class="ds-badge ds-tone-danger">✗ جواب نداد</span>'}</td></tr>`);
				const open = routeVerdictText(data.direct_open);
				rows.push(`<tr><td>مستقیم ← مقصد غیر-CF (example.com:80)</td><td><span class="ds-badge ${open.cls === "ok" ? "ds-tone-success" : "ds-tone-danger"}">${open.cls === "ok" ? "✓" : "✗"} ${open.text}</span></td></tr>`);
				const cf = routeVerdictText(data.direct_cf);
				rows.push(`<tr><td>مستقیم ← Cloudflare (104.16.132.229:443)</td><td><span class="ds-badge ${cf.cls === "ok" ? "ds-tone-success" : "ds-tone-danger"}">${cf.cls === "ok" ? "✓" : "✗"} ${cf.text}</span></td></tr>`);
				if (data.relay) {
					const r = data.relay;
					const cls = r.ok ? "ok" : "danger";
					const text = r.ok ? "رله‌ی Cloudflare سالم (400+cf-ray)" : esc(proxyTestFailText(r));
					rows.push(`<tr><td>رله‌ی ProxyIP (${esc(proxy)})</td><td><span class="ds-badge ${r.ok ? "ds-tone-success" : "ds-tone-danger"}">${r.ok ? "✓" : "✗"} ${text}</span></td></tr>`);
				}
				out.innerHTML = `<div class="ds-table-wrap"><table class="ds-table is-panel" aria-label="جدول داده‌ها"><thead><tr><th scope="col">مسیر</th><th scope="col">نتیجه</th></tr></thead><tbody>${rows.join("")}</tbody></table></div>`;
			} catch (error) {
				out.innerHTML = `<div class="ds-banner ds-tone-danger is-inline">${esc(error.message)}</div>`;
			}
		});

		$("#ping-client", host).addEventListener("click", async () => {
			const out = $("#ping-client-out", host);
			const samples = [];
			for (let i = 0; i < 5; i++) {
				const started = performance.now();
				try {
					await fetch(`/icon-64.png?cb=${Math.random()}`, { cache: "no-store" });
					samples.push(Math.round(performance.now() - started));
				} catch {
					samples.push(null);
				}
			}
			const ok = samples.filter((value) => value !== null);
			out.textContent = ok.length ? `✅ میانگین ${fa(Math.round(ok.reduce((a, b) => a + b, 0) / ok.length))} ms · کمینه ${fa(Math.min(...ok))} · بیشینه ${fa(Math.max(...ok))}` : "❌ شکست";
		});

		/* ── v2.3.13 — three browser-side diagnostics. Everything below runs
		   from the operator's own browser, exactly like the scanner's ping
		   probe: no new worker endpoints, no external service except the two
		   public DoH resolvers (disclosed in the card tooltip + education).
		   State semantics (same honesty as timedScanFetch):
		   "open" — the fetch resolved: a full round trip through the filter;
		   "rejected" — it failed fast, which still proves something answered
		   at the TCP/TLS level (expected for bare IPs: TLS certs are never
		   issued for IP literals, so the browser aborts a perfectly healthy
		   connection);
		   "timeout" — nothing came back before PROBE_TIMEOUT: port/domain
		   blackholed on this network. ── */
		const PROBE_TIMEOUT = 4000;
		const probeUrl = async (url) => {
			const ctrl = new AbortController();
			const timer = setTimeout(() => ctrl.abort(), PROBE_TIMEOUT);
			const start = performance.now();
			let state = "timeout";
			try {
				await fetch(url, { mode: "no-cors", cache: "no-store", signal: ctrl.signal });
				state = "open";
			} catch {
				state = ctrl.signal.aborted ? "timeout" : "rejected";
			}
			clearTimeout(timer);
			return { state, ms: Math.round(performance.now() - start) };
		};
		/* v3.0.1 — wording only, but it matters: a browser fetch that rejects
		   fast cannot say whether the port is closed, the certificate does not
		   cover the host, or the network reset the connection. Calling that
		   «پاسخ سریع» (or «باز») told the operator a reassuring story the
		   measurement does not support. */
		const probeBadge = (probe) => {
			if (probe.state === "open") return '<span class="ds-badge ds-tone-success">✓ پاسخ گرفت</span> <span class="dim">' + fa(probe.ms) + " ms</span>";
			if (probe.state === "rejected") return '<span class="ds-badge ds-tone-warning" title="پاسخ منفیِ سریع — مرورگر «پورت بسته»، «گواهی نامعتبر» و «ریستِ شبکه» را از هم جدا نمی‌کند">⚠ پاسخ منفی · نامشخص</span> <span class="dim">' + fa(probe.ms) + " ms</span>";
			return '<span class="ds-badge ds-tone-danger">✗ بدون پاسخ</span> <span class="dim">تایم‌اوت</span>';
		};
		const probeRow = (key, value) => '<div class="probe-row"><span class="k dim">' + key + "</span><span>" + value + "</span></div>";

		/* port tester — targets × the six HTTPS ports (config.js list via
		   window.DEVCOP), optionally the seven plain-HTTP ports too. */
		$("#port-test-run", host).addEventListener("click", async () => {
			const out = $("#port-test-out", host);
			const note = $("#port-test-note", host);
			const boot = window.DEVCOP || {};
			const tlsList = (Array.isArray(boot.tls_ports) && boot.tls_ports.length ? boot.tls_ports : ["443", "2053", "2083", "2087", "2096", "8443"]).map(String);
			const plainList = (Array.isArray(boot.plain_ports) && boot.plain_ports.length ? boot.plain_ports : ["80", "8080", "8880", "2052", "2082", "2086", "2095"]).map(String);
			const targets = $("#port-test-targets", host).value.split(/[\n,;]+/).map((t) => t.trim()).filter(Boolean).slice(0, 4);
			if (!targets.length) { out.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">حداقل یک آیپی یا دامنه بنویسید.</div>'; return; }
			const ports = $("#port-test-plain", host).checked ? [["TLS", tlsList], ["HTTP", plainList]] : [["TLS", tlsList]];
			note.textContent = "در حال آزمایش…";
			out.innerHTML = "";
			for (const target of targets) {
				const group = document.createElement("div");
				group.className = "ds-mb-3";
				group.innerHTML = '<div class="section-title mono ds-ltr">' + esc(target) + "</div>";
				out.appendChild(group);
				for (const [family, list] of ports) {
					for (const port of list) {
						const row = document.createElement("div");
						row.className = "probe-row";
						row.innerHTML = '<span class="k dim mono">' + esc(port) + (family === "TLS" ? "" : " · HTTP") + '</span><span class="dim">در حال آزمایش…</span>';
						group.appendChild(row);
						probeUrl("https://" + target + ":" + port + "/cdn-cgi/trace").then((probe) => {
							row.innerHTML = '<span class="k dim mono">' + esc(port) + (family === "TLS" ? "" : " · HTTP") + "</span><span>" + probeBadge(probe) + "</span>";
						});
					}
				}
				await new Promise((r) => setTimeout(r, 250));
			}
			note.textContent = "نتیجه فقط برای شبکه‌ی فعلی شما معتبر است.";
		});

		/* edge trace — /cdn-cgi/trace on the panel's own domain; served by the
		   Cloudflare edge itself, so it only answers on a real deployment. */
		const COLO_NAMES = { FRA: "فرانکفورت", AMS: "آمستردام", MXP: "میلان", FCO: "رم", DUB: "دوبلین", LHR: "لندن", MAN: "منچستر", CDG: "پاریس", BRU: "بروکسل", MUC: "مونیخ", DUS: "دوسلدورف", HAM: "هامبورگ", BER: "برلین", ZRH: "زوریخ", VIE: "وین", PRG: "پراگ", WAW: "ورشو", CPH: "کپنهاگ", ARN: "استکهلم", HEL: "هلسینکی", IST: "استانبول", DXB: "دبی", DOH: "دوحه", THR: "تهران", IAD: "واشنگتن", EWR: "نیوجرسی", JFK: "نیویورک", ORD: "شیکاگو", DFW: "دالاس", LAX: "لس‌آنجلس", SJC: "سن‌خوزه", SEA: "سیاتل", YTO: "تورنتو", GRU: "سائوپائولو", NRT: "توکیو", KIX: "اوساکا", SIN: "سنگاپور", HKG: "هنگ‌کنگ", ICN: "سئول", BOM: "بمبئی", DEL: "دهلی", JNB: "ژوهانسبورگ", SYD: "سیدنی", MEL: "ملبورن" };
		$("#edge-trace-run", host).addEventListener("click", async () => {
			const out = $("#edge-trace-out", host);
			const note = $("#edge-trace-note", host);
			note.textContent = "";
			out.innerHTML = '<span class="ds-spinner" aria-hidden="true"></span> در حال پرسش از لبه‌ی کلودفلر…';
			try {
				const start = performance.now();
				const res = await fetch("/cdn-cgi/trace?cb=" + Math.random(), { cache: "no-store" });
				const text = await res.text();
				const ms = Math.round(performance.now() - start);
				const map = {};
				for (const line of text.split("\n")) {
					const idx = line.indexOf("=");
					if (idx > 0) map[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
				}
				if (!map.colo) {
					out.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">پاسخ، مسیر استاندارد کلودفلر نبود (در اجرای محلی wrangler این مسیر وجود ندارد). این ابزار روی استقرار واقعی کلودفلر جواب می‌گیرد.</div>';
					return;
				}
				const city = COLO_NAMES[String(map.colo).toUpperCase()] || "";
				const warp = map.warp === "on" ? "روشن" : "خاموش (برای کاربر عادی درست است)";
				out.innerHTML =
					probeRow("دیتاسنتر (colo)", '<span class="ds-badge ds-tone-success mono">' + esc(map.colo) + "</span>" + (city ? " " + esc(city) : "")) +
					probeRow("کشور شما (loc)", '<span class="mono">' + esc(map.loc || "—") + "</span>") +
					probeRow("IP عمومی شما", '<span class="mono">' + esc(map.ip || "—") + "</span>") +
					probeRow("نسخه‌ی TLS", '<span class="mono">' + esc(map.tls || "—") + "</span>") +
					probeRow("نسخه‌ی HTTP", '<span class="mono">' + esc((map.http || "—").toUpperCase()) + "</span>") +
					probeRow("Warp", esc(warp)) +
					probeRow("زمان پاسخ", fa(ms) + " ms");
			} catch (error) {
				out.innerHTML = '<div class="ds-banner ds-tone-danger is-inline">' + esc(error.message) + "</div>";
			}
		});

		/* domain check — DoH (public Cloudflare, fallback Google) vs a real
		   domain fetch vs a direct-IP fetch; where they disagree is where the
		   network is broken. */
		const dohResolve = async (name) => {
			const endpoints = [
				["https://cloudflare-dns.com/dns-query?name=" + encodeURIComponent(name) + "&type=A", { accept: "application/dns-json" }],
				["https://dns.google/resolve?name=" + encodeURIComponent(name) + "&type=A", {}],
			];
			for (const [url, headers] of endpoints) {
				try {
					const res = await fetch(url, { headers, cache: "no-store" });
					const data = await res.json();
					const ips = (data.Answer || []).filter((a) => a.type === 1).map((a) => a.data).filter((a) => /^\d{1,3}(\.\d{1,3}){3}$/.test(a));
					if (ips.length) return { ips, source: new URL(url).host };
				} catch {}
			}
			return null;
		};
		$("#domain-check-run", host).addEventListener("click", async () => {
			const out = $("#domain-check-out", host);
			const note = $("#domain-check-note", host);
			let domain = $("#domain-check-input", host).value.trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "").toLowerCase();
			if (!/^([a-z0-9-]+\.)+[a-z]{2,}$/.test(domain)) { out.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">یک دامنه‌ی درست بنویسید (مثل example.com).</div>'; return; }
			note.textContent = "";
			out.innerHTML = '<span class="ds-spinner" aria-hidden="true"></span> در حال بررسی ' + esc(domain) + "…";
			const resolved = await dohResolve(domain);
			if (!resolved) {
				out.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">حل DNS از این شبکه ممکن نشد — حتی DoH عمومی (کلودفلر و گوگل) بی‌پاسخ بود. یا اینترنت قطع است یا فیلترینگ DNS این شبکه شدید است.</div>';
				return;
			}
			const rows = [];
			rows.push(probeRow("حل DNS (DoH عمومی)", '<span class="mono ds-ltr">' + resolved.ips.map(esc).join(" ، ") + '</span> <span class="dim">از ' + esc(resolved.source) + "</span>"));
			const byName = await probeUrl("https://" + domain + "/cdn-cgi/trace");
			rows.push(probeRow("اتصال با دامنه (DNS اپراتور + SNI)", byName.state === "open" ? '<span class="ds-badge ds-tone-success">✓ برقرار</span> <span class="dim">' + fa(byName.ms) + " ms</span>" : byName.state === "rejected" ? '<span class="ds-badge ds-tone-warning">⚠ پاسخ منفی · نامشخص</span> <span class="dim">' + fa(byName.ms) + " ms</span>" : '<span class="ds-badge ds-tone-danger">✗ بدون پاسخ</span> <span class="dim">تایم‌اوت</span>'));
			const ip = resolved.ips[0];
			const byIp = await probeUrl("https://" + ip + "/cdn-cgi/trace");
			rows.push(probeRow("اتصال مستقیم به آیپی " + ip, probeBadge(byIp)));
			let verdict;
			if (byName.state === "open") {
				verdict = '<div class="ds-banner ds-tone-info is-inline">✅ دامنه از این شبکه کاملاً در دسترس است — DNS و اتصال هر دو سالم‌اند.</div>';
			} else if (byIp.state === "open") {
				verdict = '<div class="ds-banner ds-tone-warning is-inline">⚠️ دامنه از این شبکه مسدود است ولی مستقیم به آیپی پاسخ گرفتیم — نشانه‌ی DNS آلوده یا SNI بلاک. راه‌حل همین پنل: کانفیگ با آیپی تمیز مستقیم سراغ آیپی می‌رود و به DNS و SNI وابسته نیست (آیپی از اسکنر، پورت سالم از تستر پورت‌ها).</div>';
			} else if (byIp.state === "rejected") {
