var flags_default = '/* ═══════════════════════════════════════════════════════════════════════════
   Bee.Hive Panel — country flags as inline SVG
   ─────────────────────────────────────────────────────────────────────────
   Why this file exists:

   The panel labels every exit location with a flag built from the Unicode
   regional-indicator characters (U+1F1E6…). Android and Apple ship those
   glyphs, so \u{1F1E9}\u{1F1EA} is a picture there. **Windows does not**: neither Chrome nor
   Edge nor Firefox has a flag emoji in "Segoe UI Emoji", so the very same
   string silently degrades into the two letters \xABDE\xBB — which is what the admin
   saw in the \xABافزودن لوکیشن\xBB card while the panel looked right on a phone.

   The two shortcuts were both rejected:
     • a flag CDN (flagcdn and friends) — it would make the admin's browser
       phone home once per country, leak which exits this panel uses, and break
       for operators behind filtering or on a slow link;
     • leaving the letters — the header then reads \xABDE آلمان (DE)\xBB.

   So flags are drawn here, in the bundle: no network, no font, crisp at any
   size, and it costs nothing on platforms whose emoji font already draws a
   real flag — `supportsEmojiFlags()` measures the platform once and those
   platforms keep the native emoji.

   Shapes are generated rather than stored: a Nordic cross is one function
   called five times instead of five hand-written blobs, and the American star
   field is a loop instead of 50 <circle> elements in the source. Bodies are
   built lazily and memoised, because the location cards re-render on every
   keystroke.

   Emblem honesty: coats of arms do not survive at 20 px. Where the emblem is
   what makes the flag readable it is drawn simplified (Portugal, Lebanon,
   Kenya, Mexico); where a simplification would only look wrong the country is
   left out of the table and falls back to the code chip — an honest \xABAL\xBB beats
   a misleading eagle.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
	"use strict";

	const W = 30;
	const H = 20;

	/* ── primitives ─────────────────────────────────────────────────────── */
	const r2 = (value) => Math.round(Number(value) * 100) / 100;
	const pts = (list) => list.map((point) => `${r2(point[0])},${r2(point[1])}`).join(" ");

	function rect(x, y, w, h, fill, extra) {
		return `<rect x="${r2(x)}" y="${r2(y)}" width="${r2(w)}" height="${r2(h)}" fill="${fill}"${extra || ""}/>`;
	}
	function poly(points, fill, extra) {
		return `<polygon points="${pts(points)}" fill="${fill}"${extra || ""}/>`;
	}
	function polyline(points, extra) {
		return `<polyline points="${pts(points)}"${extra || ""}/>`;
	}
	function circ(cx, cy, r, fill, extra) {
		return `<circle cx="${r2(cx)}" cy="${r2(cy)}" r="${r2(r)}" fill="${fill}"${extra || ""}/>`;
	}
	function line(x1, y1, x2, y2, stroke, width, extra) {
		return `<line x1="${r2(x1)}" y1="${r2(y1)}" x2="${r2(x2)}" y2="${r2(y2)}" stroke="${stroke}" stroke-width="${r2(width)}"${extra || ""}/>`;
	}
	function path(d, fill, extra) {
		return `<path d="${d}" fill="${fill}"${extra || ""}/>`;
	}

	/* Equal (or weighted) bands laid across the flag. */
	function bands(dir, colors, weights) {
		const sizes = weights || colors.map(() => 1);
		const total = sizes.reduce((sum, value) => sum + value, 0);
		const span = dir === "h" ? H : W;
		let out = "";
		let at = 0;
		colors.forEach((color, i) => {
			const size = (sizes[i] / total) * span;
			out += dir === "h" ? rect(0, at, W, size, color) : rect(at, 0, size, H, color);
			at += size;
		});
		return out;
	}
	const hBands = (colors, weights) => bands("h", colors, weights);
	const vBands = (colors, weights) => bands("v", colors, weights);

	/* Nordic cross: one vertical arm shifted toward the hoist, one centred.
	   `inner` is the second colour some of them carry (Norway, Iceland). */
	function nordic(bg, cross, inner, x = 10.5, arm = 4) {
		const draw = (color, width) => rect(x - width / 2, 0, width, H, color) + rect(0, H / 2 - width / 2, W, width, color);
		return rect(0, 0, W, H, bg) + (inner ? draw(cross, arm) + draw(inner, arm / 2) : draw(cross, arm));
	}

	/* n-pointed star, point up unless rotated. */
	function star(cx, cy, r, fill, rot = -90, points = 5, ratio = 0.382, extra) {
		const list = [];
		for (let i = 0; i < points * 2; i++) {
			const radius = i % 2 === 0 ? r : r * ratio;
			const a = ((rot + (i * 180) / points) * Math.PI) / 180;
			list.push([cx + radius * Math.cos(a), cy + radius * Math.sin(a)]);
		}
		return poly(list, fill, extra);
	}

	/* Crescent by subtraction: the disc, then a disc of the field colour pushed
	   to one side. `bg` must be the solid field the crescent sits on. */
	function crescent(cx, cy, rOuter, rInner, dx, dy, color, bg) {
		return circ(cx, cy, rOuter, color) + circ(cx + dx, cy + dy, rInner, bg);
	}

	/* Rays around a centre (the suns of Kyrgyzstan, Kazakhstan, Uruguay, …). */
	function rays(cx, cy, rIn, rOut, count, stroke, width, rot = -90) {
		let out = "";
		for (let i = 0; i < count; i++) {
			const a = ((rot + (i * 360) / count) * Math.PI) / 180;
			out += line(cx + rIn * Math.cos(a), cy + rIn * Math.sin(a), cx + rOut * Math.cos(a), cy + rOut * Math.sin(a), stroke, width);
		}
		return out;
	}

	/* Zigzag boundary between a hoist band and the field (Gulf flags): `teeth`
	   white points biting into the coloured field. */
	function serrated(bandWidth, teeth, bandColor, fieldColor) {
		const step = H / teeth;
		const points = [[0, 0]];
		for (let i = 0; i < teeth; i++) {
			points.push([bandWidth + step * 0.6, i * step + step * 0.5]);
			points.push([bandWidth, (i + 1) * step]);
		}
		points.push([0, H]);
		return rect(0, 0, W, H, fieldColor) + poly(points, bandColor);
	}

