	/* ── settings ─────────────────────────────────────────────────────── */
	/* Each settings visit starts folded. Toggling only changes the clicked
	   card's visibility, never re-renders fields or changes sibling state. */
	function applyCollapsedCard(card, collapsed) {
		const open = !collapsed;
		card.classList.toggle("is-open", open);
		const panel = card.querySelector(":scope > .ds-accordion-panel");
		if (panel) panel.hidden = !open;
		const head = card.querySelector("[data-collapse-toggle]");
		if (head) head.setAttribute("aria-expanded", open ? "true" : "false");
	}

	function wireCollapsibleCards(root) {
		const host = root || document;
		for (const card of host.querySelectorAll("[data-collapse]")) {
			const head = card.querySelector("[data-collapse-toggle]");
			if (!head || head.dataset.collapseWired === "1") continue;
			applyCollapsedCard(card, true);
			head.dataset.collapseWired = "1";
			head.addEventListener("click", () => {
				applyCollapsedCard(card, card.classList.contains("is-open"));
			});
		}
	}

