								<a class="ds-btn is-sm is-ghost" href="https://github.com/patterniha/PattNG" target="_blank" rel="noopener noreferrer"><svg class="ico" aria-hidden="true"><use href="#i-phone"/></svg><span>PattNG</span></a>
								<a class="ds-btn is-sm is-ghost" href="https://github.com/patterniha/PattN" target="_blank" rel="noopener noreferrer"><svg class="ico" aria-hidden="true"><use href="#i-monitor"/></svg><span>PattN</span></a>
							</div>
						</div>
					</div>
				</div>
			</div>

			<div data-pane="ips" hidden>
				<div class="user-ip-layout">
					<div class="user-ip-addresses">${area("ips", "آیپی‌های تمیز این کاربر", "", 4)}</div>
				<div class="user-ip-options">
					<label class="ds-field"><span class="ds-field-label">اپراتور استخر ${hintMarkup("«همه‌ی استخرها» = چرخش از مجموعِ همه‌ی استخرهای ذخیره‌شده.\nانتخاب یک استخر = همان لحظه به‌اندازه‌ی «تعداد IP اختصاصی» آیپی از همان استخر در کادر کنار درج می‌شود.\n«آیپی‌های دستی» = ارتباط با استخرها قطع می‌شود و فقط آیپی‌هایی که خودتان در کادرِ «آیپی‌های تمیز این کاربر» وارد کنید برای این کاربر استفاده می‌شود.\nبا «چرخش خودکار آیپی» روشن، هر N دقیقه آیپی‌های فعلی با آیپی‌های جدیدِ غیرتکراری از همان منبع جایگزین می‌شوند.\n«تعداد IP اختصاصی» باید از آیپی‌های مخزن بیشتر نباشد؛ مخزن‌های کمتر از ۱۰ آیپی مقدار پیشنهادیِ نصفِ گرد‌شده به پایین می‌گیرند.")}</span>
						<span class="ds-select-wrap"><select class="ds-input ds-select" name="ip_operator" id="user-pool-select">
							<option value="all" ${poolSelectValue === "all" ? "selected" : ""}>همه‌ی استخرها</option>
							<option value="manual" ${poolSelectValue === "manual" ? "selected" : ""}>آیپی‌های دستی</option>
							${namedPools.length ? `<optgroup label="استخرهای ذخیره‌شده">${namedPools.map((pool) => `<option value="pool:${esc(pool.name)}" ${poolSelectValue === `pool:${pool.name}` ? "selected" : ""}>${esc(pool.name)} (${fa(pool.ips.length)} IP)</option>`).join("")}</optgroup>` : ""}
							${poolOperators.length ? `<optgroup label="اپراتورها (استخر عمومی)">${poolOperators.map((op) => `<option value="${esc(op)}" ${poolSelectValue === op ? "selected" : ""}>${esc(op)}</option>`).join("")}</optgroup>` : ""}
						</select><svg class="ds-select-caret" aria-hidden="true"><use href="#i-chevron-down"/></svg></span>
					</label>
					<div class="user-ip-counts">
						${input("ip_count", "تعداد IP اختصاصی", "", "number", d.ip_count ?? 8)}
						<label class="ds-field"><span class="ds-field-label">چرخش هر N دقیقه</span>
							<input class="ds-input" type="number" name="rotate_time" value="${val("rotate_time", d.rotate_time ?? 0)}" step="any">
						</label>
					</div>
				</div>
				</div>
				${swField("auto_rotate_ip", "چرخش خودکار آیپی", "", d.auto_rotate_ip ?? 0)}
				<span class="ds-field-help dim ds-switch-help" id="manual-mode-tip"></span>

				<div class="section-title group-start">🌍 لوکیشن‌های خروجی <span class="hint warn" data-tip="هر کارت یک خروجی مستقل است.\nپروکسی رایگان = ناشناس — قبل تحویل تست کنید.\nN آیپی × M لوکیشن = N×M کانفیگ." tabindex="0" role="note" aria-label="هشدار پروکسی عمومی">⚠</span></div>


				<div class="ds-actions ds-my-2 ds-wrap">
					<button type="button" class="ds-btn is-sm is-primary" id="btn-add-location-card"><svg class="ico" aria-hidden="true"><use href="#i-plus"/></svg><span>افزودن لوکیشن</span></button>
					<button type="button" class="ds-btn is-sm" id="btn-test-all-locs"><svg class="ico" aria-hidden="true"><use href="#i-zap"/></svg><span>تست پینگ همه</span></button>
				</div>
				<div id="user-locations"></div>
				<div class="section-title group-start">External Raw Configs</div>
				<label class="ds-field full"><span class="ds-field-label">کانفیگ‌های خارجی این کاربر</span>
					<textarea class="ds-input is-mono mono" name="external_raw_configs" rows="5" placeholder="هر کانفیگ در یک خط؛ vless://، vmess://، trojan://، ss://، ssr://، hysteria2://، tuic://">${val("external_raw_configs", "")}</textarea>
					<span class="ds-field-help">لینک‌های مستقیم کانفیگ را هرکدام در یک خط وارد کنید. این موارد به اشتراک متنی کاربر اضافه می‌شوند؛ URL اشتراک راه دور را اینجا وارد نکنید.</span></label>
				<textarea class="ds-input is-mono" name="user_socks5" aria-hidden="true" tabindex="-1" hidden>${val("user_socks5", "")}</textarea>
				<div id="user-proxy-result" class="ds-mt-3"></div>
				<button type="button" id="btn-test-user-proxy" tabindex="-1" hidden></button>
			</div>

			<div data-pane="filter" hidden>
				${swField("block_porn", "مسدودسازی محتوای بزرگسال")}
				${swField("block_ads", "مسدودسازی تبلیغات")}
				${swField("ir_direct", "عبور مستقیم سایت‌های ایرانی", "", d.ir_direct ?? 0)}
			</div>
		</form>`;

		const footer = `
			<button class="ds-btn is-primary" id="user-save">${isEdit ? `<svg class="ico" aria-hidden="true"><use href="#i-save"/></svg><span>ذخیره تغییرات</span>` : `<svg class="ico" aria-hidden="true"><use href="#i-plus"/></svg><span>ساخت کاربر</span>`}</button>
			<button class="ds-btn is-ghost" data-close>انصراف</button>`;

		const modal = openModal({ title: isEdit ? `ویرایش کاربر: ${esc(existing.username)}` : "کاربر جدید", body, footer });
		applyDpiPreset(modal.root);
		$$("[data-patterniha]", modal.root).forEach((btn) => btn.addEventListener("click", () => {
			fillPatterniha(modal.root, btn.dataset.patterniha);
		}));
		injectHints(modal.root);
		wirePublicProxies(modal.root);
		wireDpiModes(modal.root);
		wirePorts(modal.root);
		renderLocations(modal.root);
		/* Picking a named pool immediately fills this user's clean-IP box with
		   «تعداد IP اختصاصی» addresses from that pool — the same pool the
		   N-minute rotation keeps drawing from. */
		const poolSelect = $("[name=\"ip_operator\"]", modal.root);
		/* «آیپی‌های دستی» cuts every tie to the pools (v2.3.3): the count and
		   rotation fields grey out, and the rotation switch itself goes dark
		   and non-activatable — exactly like «جایگزینی خودکار پروکسی خراب» on
		   a manual location. Leaving manual mode re-arms that switch (the
		   operator just picked a pool, so daily rotation — the new default —
		   works out of the box) and prefills 1440 when N was empty/zero. */
		let manualZeroed = false;
		const syncManualMode = () => {
			const manual = String(poolSelect?.value || "") === "manual";
			for (const name of ["ip_count", "rotate_time"]) {
				const field = $(`[name="${name}"]`, modal.root);
				if (field) field.disabled = manual;
			}
			const autoSwitch = $("[name=\"auto_rotate_ip\"]", modal.root);
			if (manual) {
				if (autoSwitch) {
					autoSwitch.checked = false;
					autoSwitch.disabled = true;
				}
				manualZeroed = true;
			} else if (autoSwitch) {
				autoSwitch.disabled = false;
				if (manualZeroed) {
					autoSwitch.checked = true;
					const rotate = $("[name=\"rotate_time\"]", modal.root);
					if (rotate && !Number(rotate.value)) rotate.value = "1440";
					manualZeroed = false;
				}
			}
			const tip = $("#manual-mode-tip", modal.root);
			if (tip) {
				tip.textContent = manual
					? "اپراتور استخر روی «آیپی‌های دستی» است؛ چرخش از استخرها بی‌معناست و غیرفعال شد."
					: "روشن = هر N دقیقه از منبع انتخاب‌شده (استخر یا همه‌ی استخرها) تازه می‌شود.";
			}
		};
		/* v2.3.4 — pool-size-aware filling:
		   • more IPs than the pool holds is refused (error toast, nothing filled);
		   • a pool with fewer than 10 IPs cannot feed a healthy rotation, so the
		     suggested count floor(P/2) — never 0, so no zero-division/empty fill —
		     is placed in the field (and filled) instead;
		   • otherwise the entered count is filled exactly. floor(P/2) also
		     guarantees the ≥2× headroom the rotation needs to hand out a fully
		     fresh, non-overlapping window every cycle. */
		const fillFromPool = (candidates, count, message) => {
			const ipsField = $("[name=\"ips\"]", modal.root);
			const picked = [...candidates].sort(() => Math.random() - 0.5).slice(0, count);
			if (ipsField) ipsField.value = picked.join("\n");
			toast(message, "ok");
		};
		let poolSizeForCount = 0; /* 0 = no pool selected (manual) */
		poolSelect?.addEventListener("change", () => {
			const value = String(poolSelect.value || "");
			syncManualMode();
			const countInput = $("[name=\"ip_count\"]", modal.root);
			const entered = Math.max(1, Math.min(500, Number(countInput?.value) || 8));
			if (value === "manual") {
				poolSizeForCount = 0;
				const ipsField = $("[name=\"ips\"]", modal.root);
				ipsField?.focus();
				toast("ارتباط با استخرها قطع شد — آیپی‌های دلخواه را در کادر «آیپی‌های تمیز این کاربر» وارد کنید.", "ok");
				return;
			}
			/* «همه‌ی استخرها» fills from the union of every saved pool. */
			const candidates = value === "all"
				? [...new Set((state.pools || []).flatMap((pool) => pool.ips))]
				: (() => {
					const pool = (state.pools || []).find((entry) => entry.name === value.slice(5));
					return pool ? [...pool.ips] : null;
				})();
			if (!candidates) return;
			if (!candidates.length) {
				poolSizeForCount = 0;
				toast("هنوز استخری ذخیره نشده است — اول از تب «آیپی تمیز» استخر بسازید.", "warn");
				return;
			}
			const poolSize = candidates.length;
			poolSizeForCount = poolSize;
			const suggested = Math.max(1, Math.floor(poolSize / 2)); /* never 0 — no zero-fill */
			if (entered > poolSize) {
				if (poolSize < 10) {
					if (countInput) countInput.value = String(suggested);
					fillFromPool(candidates, suggested, `تعداد واردشده (${fa(entered)}) بیشتر از آیپی‌های مخزن (${fa(poolSize)}) است — مخزن کمتر از ۱۰ آیپی دارد؛ مقدار پیشنهادی ${fa(suggested)} درج شد.`);
				} else {
					toast(`بیشتر از تعداد آیپی مخزن (${fa(poolSize)}) نمی‌توان وارد کرد.`, "err");
				}
				return;
			}
			if (poolSize < 10 && suggested !== entered) {
				if (countInput) countInput.value = String(suggested);
				fillFromPool(candidates, suggested, `مخزن ${value === "all" ? "همه‌ی استخرها" : `استخر «${esc(value.slice(5))}»`} فقط ${fa(poolSize)} آیپی دارد (کمتر از ۱۰) — تعداد پیشنهادی ${fa(suggested)} درج شد تا چرخش همیشه آیپی‌های تازه بدهد.`);
				return;
			}
			fillFromPool(candidates, entered, value === "all" ? `${fa(entered)} آیپی از همه‌ی استخرها درج شد.` : `${fa(entered)} آیپی از استخر «${esc(value.slice(5))}» درج شد.`);
		});
		/* Editing the count while a pool is selected gets the same guard, so an
		   impossible value can never be saved quietly. */
		$("[name=\"ip_count\"]", modal.root)?.addEventListener("change", () => {
			if (!poolSizeForCount) return;
			const countInput = $("[name=\"ip_count\"]", modal.root);
			const entered = Math.max(1, Math.min(500, Number(countInput?.value) || 8));
			if (entered > poolSizeForCount) {
				if (countInput) countInput.value = String(poolSizeForCount);
				toast(`بیشتر از تعداد آیپی مخزن (${fa(poolSizeForCount)}) نمی‌توان وارد کرد.`, "err");
			}
		});
		syncManualMode();

		/* The note only takes room when it is wanted: the switch reveals the card.
		   Turning it off clears the note on save, which is what "off" should mean —
		   an existing note starts with the switch on, so nothing is lost by accident. */
		const noteToggle = $("#note-toggle", modal.root);
		const noteBox = $("#note-box", modal.root);
		if (noteToggle && noteBox) {
			const syncNote = () => {
				noteBox.hidden = !noteToggle.checked;
			};
			noteToggle.addEventListener("change", syncNote);
			syncNote();
		}

		/* DS runtime wires click, roving focus and RTL-aware arrow navigation. */
		window.DevCopUI.enhance(modal.root);

		/* One dice, two meanings — because a stored UUID is immutable: db.js skips
		   `uuid` on update and only honours `regenerate_uuid`. Filling the box for an
		   existing user would have been discarded on save without a word, so in edit
		   mode the dice performs the real server-side regeneration, behind the warning
		   that the user's previous configs stop working. */
		$("#btn-gen-uuid", modal.root).addEventListener("click", async () => {
			if (!isEdit) {
				$('input[name="uuid"]', modal.root).value = newUuid();
				toast("UUID جدید ساخته شد 🎲", "ok");
				return;
			}
			if (!(await confirmDialog("UUID جدید ساخته شود؟ کانفیگ‌های قبلی این کاربر از کار می‌افتند.", { confirmText: "بساز" }))) return;
			try {
				await api.put(`/api/users/${encodeURIComponent(existing.username)}`, { regenerate_uuid: true });
				toast("UUID جدید ساخته شد.", "ok");
				modal.close();
				await loadUsers();
				render();
			} catch (error) {
				toast(error.message, "err");
			}
		});

		const testBtn = $("#btn-test-user-proxy", modal.root);
		if (testBtn) {
			testBtn.addEventListener("click", async () => {
				const out = $("#user-proxy-result", modal.root);
				// new behavior: if editing existing user use server-stored proxies, otherwise test current form cards
				out.innerHTML = '<span class="ds-spinner" aria-hidden="true"></span> در حال تست…';
				try {
					if(isEdit){
						const data = await api.post("/api/tools/test-user-proxy", { username: existing.username });
						out.innerHTML = renderProxyResults(data.results || [], data.message);
					} else {
						const list = readLocations(modal.root);
						const proxies = list.map(e=>e.proxy).filter(Boolean);
						if(!proxies.length){ out.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">هنوز لوکیشنی وارد نکرده‌اید.</div>'; return; }
						const data = await api.post("/api/tools/test-proxy", {proxies});
						out.innerHTML = renderProxyResults(data.results || []);
					}
				} catch (error) {
					out.innerHTML = `<div class="ds-banner ds-tone-danger is-inline">${esc(error.message)}</div>`;
				}
			});
		}

		$("#user-save", modal.root).addEventListener("click", async () => {
			const formEl = $("#user-form", modal.root);
			const data = Object.fromEntries(new FormData(formEl).entries());
			/* Every field wearing an asterisk is checked here, and the failure moves
			   to the pane that holds it: a server-side 400 would leave the operator
			   guessing which of the five tabs to open. */
			const goTab = (name) => $(`.ds-tabbar-item[data-tab="${name}"]`, modal.root)?.click();
			const emptyRequired = [
				{ key: "username", tab: "basic", message: "نام کاربری نمی‌تواند خالی باشد." },
				{ key: "uuid", tab: "basic", message: "UUID نمی‌تواند خالی باشد." },
			].find((entry) => !String(data[entry.key] || "").trim());
			if (emptyRequired) {
				goTab(emptyRequired.tab);
				window.DevCopUI.fieldError($(`[name="${emptyRequired.key}"]`, modal.root), emptyRequired.message);
				$(`[name="${emptyRequired.key}"]`, modal.root)?.focus();
				return toast(emptyRequired.message, "err");
			}
			const protocols = [data.proto_vless ? "vless" : null, data.proto_trojan ? "trojan" : null].filter(Boolean);
			if (!protocols.length) {
				goTab("basic");
				return toast("دست‌کم یک پروتکل را انتخاب کنید.", "err");
			}
			if (!String(data.port || "").trim()) {
				goTab("conn");
				return toast("دست‌کم یک پورت انتخاب کنید.", "err");
			}
			/* A blank card must never be saved: the server keys `/loc-N` by position
			   in this list, so a stored blank would shift every location after it and
			   the links already handed to the user would point at a different exit.
			   The panel blocks the save and opens the offending card instead. */
			const slots = readLocations(modal.root);
			const emptySlot = firstEmptyLocation(slots);
			if (emptySlot > -1) {
				goTab("ips");
				modal.root._expandedLoc = emptySlot;
				renderLocations(modal.root);
				return toast(`لوکیشن ${fa(emptySlot + 1)} خالی است — پروکسی را وارد کنید یا اسلات را حذف کنید.`, "err");
			}
			/* v2.3.8 — پاک‌کردن جعبه‌ی آیپی‌های تمیز و زدنِ ذخیره، انتخابِ صریح
			   «آیپی‌های دستی» است: اتصال به استخر نمی‌ماند، وگرنه چرخشِ بعدی
			   بی‌خبر جعبه را از همان استخر دوباره پر می‌کرد. */
			const rawOperator = String(data.ip_operator || "");
			const manualized = !String(data.ips || "").trim() && (rawOperator.startsWith("pool:") || rawOperator === "all");
			const opValue = manualized ? "manual" : rawOperator;
			if (manualized) toast("جعبه‌ی آیپی خالی است — اپراتور به «آیپی‌های دستی» تغییر کرد.", "ok");
			const payload = {
				username: data.username.trim(),
				uuid: data.uuid ? data.uuid.trim() : undefined,
				connection_type: protocols.length ? protocols.join("+") : "vless",
				note: noteToggle && !noteToggle.checked ? null : data.note || null,
				/* Active/inactive is a list-level action (⏸/▶️) now, so the form no
				   longer carries it: keep what is stored, start new users active. */
				is_active: isEdit ? Number(existing.is_active ?? 1) : 1,
				limit_gb: Number(data.limit_gb || 0) || null,
				expiry_days: Number(data.expiry_days || 0) || null,
				limit_req: Number(data.limit_req || 0) || null,
				ip_limit: Number(data.ip_limit || 0) || null,
				auto_reset_vol_days: Number(data.auto_reset_vol_days || 0),
				auto_reset_req_days: Number(data.auto_reset_req_days || 0),
				start_on_first_connect: data.start_on_first_connect ? 1 : 0,
				tls: data.tls,
				port: data.port,
				fingerprint: data.fingerprint,
				enable_direct: data.enable_direct ? 1 : 0,
				frag_len: data.frag_len,
				frag_int: data.frag_int,
				advanced_frag: data.advanced_frag || null,
				cipher_suites: data.cipher_suites || null,
				tls_mask: data.tls_mask || null,
				ips: data.ips || null,
				external_raw_configs: data.external_raw_configs || null,
				/* v2.3.2 mapping: pool:<name> → that pool; all → '*' (union of
				   every pool); manual → no pool and ip_operator 'manual', which
				   the rotation job skips entirely; legacy operator names pass
				   through untouched for old installs. */
				ip_operator: opValue.startsWith("pool:") || opValue === "all" ? "all" : opValue || "manual",
				ip_pool: opValue.startsWith("pool:") ? opValue.slice(5) : opValue === "all" ? "*" : null,
				ip_count: Number(data.ip_count || 8),
				rotate_time: Number(data.rotate_time || 0),
				auto_rotate_ip: data.auto_rotate_ip ? 1 : 0,
				/* Only filled cards reach the database; the check above already
				   refused a blank one, and this keeps that promise locally too. */
				user_socks5: locationFieldValue(slots) ?? normalizeProxyField(data.user_socks5),
				auto_rotate_user_proxy: 0, // legacy global switch is no longer used
				block_porn: data.block_porn ? 1 : 0,
				block_ads: data.block_ads ? 1 : 0,
				ir_direct: data.ir_direct ? 1 : 0,
			};
			$("#user-save", modal.root).disabled = true;
			try {
				/* v2.3.4: the links page no longer opens by itself after creation —
				   the operator opens it from the table (row action «لینک‌ها»). */
				if (isEdit) {
					await api.put(`/api/users/${encodeURIComponent(existing.username)}`, payload);
					toast("تغییرات ذخیره شد ✅", "ok");
				} else {
					const created = await api.post("/api/users", payload);
					toast(`کاربر «${created.user.username}» ساخته شد ✅`, "ok");
				}
				modal.close();
				await loadUsers();
				render();
			} catch (error) {
				toast(error.message, "err");
				$("#user-save", modal.root).disabled = false;
			}
		});

	}

	/* ── ساخت سریع کاربر — میانبر یک‌کلیکی (v3.0.4) ─────────────────────
	   One click, one user with four real exits. The flow is deliberately
	   automatic and visibly so: a progress line fills while the panel fetches
	   the free list, pings candidates country by country over both protocols,
	   picks the protocol that actually produced healthy exits, and creates an
	   ordinary user with a random username. Every choice it made is written
	   into the log as it happens, so the speed never hides the reasoning.
	   The created user has «اتصال مستقیم» off (with direct on, the Worker's
	   own route wins and the locations become decoration), no clean-IP ties,
	   and the per-slot auto-replace opt-in on every location. */
	/* v3.0.6 — after the last step the progress block waits this long at 100%,
	   then fades out over QUICK_FADE_MS, and only then the result is shown. */
	const QUICK_DONE_DELAY_MS = 2000;
	const QUICK_FADE_MS = 600;
	const pause = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
	const QUICK_LOCATIONS = 4;    /* the promise: four exits */
	const QUICK_PER_COUNTRY = 4;  /* candidates pinged per country, per round */
	const QUICK_ROUNDS = 2;       /* a free list is a lottery: try the next four */
	/* v3.0.7 — only countries whose free pool holds at least this many proxies are
	   candidates. A thin country has too few exits to pick the quickest from. */
	const QUICK_MIN_PROXIES = 6;
	const QUICK_PROTOCOLS = ["socks5", "http"];
	/* Probes per test request. The API runs one request's probes side by side
	   (five at a time), so small requests that all go out together finish in about
	   the time of their slowest probe. */
	const QUICK_BATCH = 5;
	/* A test request that has not answered by then counts as silent. */
	const QUICK_TEST_TIMEOUT_MS = 30000;

	/* Country buckets of a fetched pool, most-populated first. */
	function mlCountryGroups(pool, pinned = "") {
		const groups = new Map();
		for (const entry of pool) {
			const code = String(entry?.country || "").trim().toUpperCase();
			if (!/^[A-Z]{2}$/.test(code)) continue;
			if (!groups.has(code)) groups.set(code, []);
			groups.get(code).push(entry);
		}
		return [...groups.entries()]
			.map(([code, entries]) => ({ code, entries }))
			.filter((group) => group.entries.length >= QUICK_MIN_PROXIES)
			.sort((a, b) => ((a.code === pinned ? -1 : b.code === pinned ? 1 : 0)) || (b.entries.length - a.entries.length) || a.code.localeCompare(b.code));
	}

	/* Ranking and picking are pure functions so the promise — «the protocol
	   that actually produced healthy exits wins, then the four lowest-latency
	   exits, one per country» — is testable without a browser or a network. */
	function quickRankProtocols(scores) {
		return [...(scores || [])]
			.filter((score) => score?.wins?.length)
			.sort((a, b) => (b.wins.length - a.wins.length) || (a.mean - b.mean));
	}
	function quickPickSlots(scores, limit = QUICK_LOCATIONS) {
		const ranked = quickRankProtocols(scores);
		const used = new Set();
		const chosen = [];
		const take = (wins) => {
			for (const win of [...wins].sort((a, b) => a.latency - b.latency)) {
				if (chosen.length >= limit) return;
				if (used.has(win.country)) continue;
				used.add(win.country);
				chosen.push(win);
			}
		};
		if (ranked.length) take(ranked[0].wins);
		/* Fewer healthy exits than promised on the better protocol? Top up from
		   the other one instead of quietly shipping a shorter list. */
		for (const score of ranked.slice(1)) take(score.wins);
		return { ranked, chosen };
	}

	/* A list cut into requests of at most `size` items, order kept. */
	function quickChunk(items, size) {
		const chunks = [];
		for (let offset = 0; offset < items.length; offset += size) chunks.push(items.slice(offset, offset + size));
		return chunks;
	}

	/* `user-` + five letters/digits from an unambiguous alphabet: short enough
	   to type, random enough not to collide, and never a name that looks like
	   the operator's own naming scheme. */
	function randomUsername() {
		const alphabet = "abcdefghjkmnpqrstuvwxyz23456789";
		const bytes = new Uint8Array(5);
		crypto.getRandomValues(bytes);
		return `user-${Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join("")}`;
	}

	function quickUserModal() {
		const modal = openModal({
			title: "ساخت سریع کاربر",
			size: "sm",
			center: true,
			body: `<div class="quick-build" dir="rtl">
				<div class="quick-progress">
					<div class="ds-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-label="پیشرفت ساخت"><div class="ds-progress-track"><span class="ds-progress-fill" style="--ds-progress:0"></span></div></div>
					<div class="quick-pct" aria-hidden="true">۰٪</div>
					<div class="quick-log" role="status" aria-live="polite"></div>
				</div>
			</div>`,
		});
		const bar = $(".ds-progress-fill", modal.root);
		const pct = $(".quick-pct", modal.root);
		const log = $(".quick-log", modal.root);
		const body = $(".quick-build", modal.root);

		const say = (text, kind) => {
			const line = document.createElement("div");
			line.className = `quick-line${kind ? ` ${kind}` : ""}`;
			line.innerHTML = `<span class="quick-dot" aria-hidden="true"></span><span>${esc(text)}</span>`;
			log.appendChild(line);
			/* Keep the newest line in view without stealing focus. */
			log.scrollTop = log.scrollHeight;
		};
		const step = (percent, text) => {
			const value = Math.max(0, Math.min(100, Math.round(percent)));
			bar.style.setProperty("--ds-progress", String(value / 100));
			pct.textContent = `${fa(value)}٪`;
			bar.closest("[role='progressbar']").setAttribute("aria-valuenow", String(value));
			if (text) say(text);
		};

		/* One country → one real exit: the four fastest healthy addresses of a
		   country are pinged in a round, and the winner is the quickest one. Every
		   candidate of a round goes out at once, cut into small requests of
		   QUICK_BATCH probes that the API runs side by side. A round therefore lasts
		   as long as its slowest request instead of the sum of all of them. */
		function quickBatches(plan, round) {
			return plan.groups
				.map((group) => ({ group, candidates: group.entries.slice(round * QUICK_PER_COUNTRY, (round + 1) * QUICK_PER_COUNTRY) }))
				.filter((batch) => batch.candidates.length && !batch.group.win);
		}
		function quickRequests(plan, round) {
			return quickChunk(quickBatches(plan, round).flatMap((batch) => batch.candidates.map((entry) => entry.url)), QUICK_BATCH);
		}
		function withDeadline(promise, ms) {
			let timer;
			return Promise.race([
				promise,
				new Promise((_, reject) => { timer = setTimeout(() => reject(new Error("زمان تست تمام شد")), ms); }),
			]).finally(() => clearTimeout(timer));
		}
		async function huntExit(plan, round, onRequest) {
			const batches = quickBatches(plan, round);
			const requests = quickRequests(plan, round);
			if (!requests.length) return;
			const results = new Map();
			await Promise.all(requests.map(async (proxies) => {
				try {
					const data = await withDeadline(api.post("/api/tools/test-proxy", { proxies, geo: false }), QUICK_TEST_TIMEOUT_MS);
					for (const result of data.results || []) results.set(result.proxy, result);
				} catch (error) {
					say(`یک دسته تست نشد: ${error.message || "خطای شبکه"}`, "warn");
				} finally {
					onRequest();
				}
			}));
			for (const batch of batches) {
				const best = batch.candidates
					.map((entry) => ({ entry, result: results.get(entry.url) }))
					.filter((row) => row.result?.ok)
					.sort((a, b) => (a.result.latency ?? Number.MAX_SAFE_INTEGER) - (b.result.latency ?? Number.MAX_SAFE_INTEGER))[0];
				if (!best) continue;
				batch.group.win = { protocol: plan.protocol, country: batch.group.code, entry: best.entry, latency: Math.round(best.result.latency || 0) };
			}
		}

		async function build() {
			step(4, "شروع…");
			/* ── ۱: فهرست هر دو پروتکل ─────────────────────────────────── */
			step(8, `واکشی فهرست رایگان برای ${fa(QUICK_PROTOCOLS.length)} پروتکل…`);
			const plans = await Promise.all(QUICK_PROTOCOLS.map(async (protocol) => {
				try {
					/* `country: ""` is deliberate — the settings default would pin
					   the whole thing to one country. */
					const data = await api.post("/api/tools/public-proxies", { protocol, limit: 500, country: "" });
					const list = (data.proxies || []).filter((entry) => String(entry?.country || "").trim());
					if (!list.length) say(`${protocol}: فهرست خالی برگشت${data.errors?.length ? ` (${data.errors[0]?.error || "خطای شبکه"})` : ""}.`, "warn");
					return { protocol, list, groups: mlCountryGroups(list) };
				} catch (error) {
					say(`${protocol}: واکشی نشد — ${error.message || "خطای نامشخص"}.`, "warn");
					return { protocol, list: [], groups: [] };
				}
			}));
			const live = plans.filter((plan) => plan.groups.length);
			if (!live.length) throw new Error(`هیچ کشوری در فهرست رایگان به ${fa(QUICK_MIN_PROXIES)} پروکسی نرسید؛ یک بار دیگر تلاش کنید.`);
			for (const plan of live) say(`${plan.protocol}: ${fa(plan.list.length)} کاندید در ${fa(plan.groups.length)} کشور.`);
			step(24);

			/* ── ۲: پینگ کاندیدها — هر دور، همه‌ی پروتکل‌ها هم‌زمان ───────── */
			let round = 0;
			let planned = 0;
			let answered = 0;
			/* The bar follows finished requests, so it moves while the probes run. */
			const progress = () => step(26 + ((round + (planned ? answered / planned : 1)) / QUICK_ROUNDS) * 48);
			const answer = () => { answered++; progress(); };
			const winsNow = () => live.reduce((sum, plan) => sum + plan.groups.filter((group) => group.win).length, 0);
			step(26, "پینگ کاندیدها — هر کشور چهار کاندید در هر دور…");
			for (round = 0; round < QUICK_ROUNDS; round++) {
				planned = live.reduce((sum, plan) => sum + quickRequests(plan, round).length, 0);
				answered = 0;
				if (!planned) continue;
				const before = winsNow();
				say(`دور ${fa(round + 1)}: ${fa(planned)} درخواست تست، همه با هم…`);
				await Promise.all(live.map((plan) => huntExit(plan, round, answer)));
				say(`دور ${fa(round + 1)} تمام شد: ${fa(winsNow() - before)} خروج سالم پیدا شد.`, "ok");
			}

			/* ── ۳: بهترین پروتکل ──────────────────────────────────────── */
			const scores = live.map((plan) => {
				const wins = plan.groups.map((group) => group.win).filter(Boolean);
				const mean = wins.length ? wins.reduce((sum, win) => sum + win.latency, 0) / wins.length : Number.MAX_SAFE_INTEGER;
				return { protocol: plan.protocol, wins, mean };
			});
			const { ranked, chosen } = quickPickSlots(scores);
			const best = ranked[0];
			for (const score of ranked) {
				if (score.protocol !== best.protocol) say(`${score.protocol}: ${fa(score.wins.length)} خروج سالم.`);
			}
			step(76, `بهترین پروتکل: ${best.protocol} — ${fa(best.wins.length)} خروج سالم${best.wins.length ? ` (میانگین ${fa(Math.round(best.mean))} میلی‌ثانیه)` : ""}.`);

			/* ── ۴: چهار خروج کم‌پینگ ─────────────────────────────────── */
			if (chosen.length < QUICK_LOCATIONS && ranked.length > 1) {
				say(`برای رسیدن به ${fa(QUICK_LOCATIONS)} لوکیشن از پروتکل دیگر هم برداشته می‌شود…`, "warn");
			}
			const slots = chosen
				.slice()
				.sort((a, b) => a.latency - b.latency)
				.map((win) => {
					say(`${countryLabel({ country: win.country, country_name: win.entry.country_name })}: ${win.protocol} · ${fa(win.latency)} میلی‌ثانیه ✓`, "ok");
					return { proxy: win.entry.url, country: win.country, country_name: win.entry.country_name || null, source: "public", auto_replace: true };
				});
			if (slots.length < 2) throw new Error("خروج سالم کافی پیدا نشد؛ یک بار دیگر بزنید — فهرست رایگان هر ساعت عوض می‌شود.");

			/* ── ۵: ساخت کاربر ────────────────────────────────────────── */
			step(84, "ساخت کاربر…");
			let created = null;
			let username = randomUsername();
			for (let attempt = 0; attempt < 4 && !created; attempt++) {
				try {
					created = await api.post("/api/users", {
						username,
						is_active: 1,
						/* Off on purpose: with direct on, the Worker's own route
						   wins and every location below becomes decoration. */
						enable_direct: 0,
						ips: null,
						ip_operator: "manual",
						ip_pool: null,
						ip_count: 0,
						rotate_time: 0,
						auto_rotate_ip: 0,
						user_socks5: JSON.stringify(slots),
						auto_rotate_user_proxy: 0,
					});
				} catch (error) {
					/* The random name is short: a collision is possible, and the
					   server is the one that knows. Roll again instead of failing. */
					if (!/ثبت شده/.test(String(error?.message || ""))) throw error;
					say(`نام «${username}» تکراری بود — نام تازه گرفته شد.`, "warn");
					username = randomUsername();
				}
			}
			if (!created) throw new Error("ساخت کاربر بعد از چند تلاش نام‌گذاری نشد.");
			step(100);
			say(`کاربر «${created.user.username}» با ${fa(slots.length)} خروج واقعی ساخته شد.`, "ok");
			await showResult(() => finish(created.user.username, slots.length));
			await Promise.all([loadUsers(), loadOverview()]);
			if (state.page === "users" || state.page === "dashboard") render();
		}

		/* v3.0.7 — the bar and the log stay for QUICK_DONE_DELAY_MS at 100% (or at the
		   point a failure happened), fade out on their own, and only then the result
		   view replaces them. The result never sits underneath the progress. */
		async function showResult(render) {
			await pause(QUICK_DONE_DELAY_MS);
			const fading = $(".quick-progress", modal.root);
			if (fading) fading.classList.add("is-leaving");
			await pause(QUICK_FADE_MS);
			if (fading) fading.hidden = true;
			render();
		}

		function finish(username, count) {
			const done = document.createElement("div");
			done.className = "quick-done";
			done.dir = "rtl";
			done.innerHTML = `
				<div class="quick-done-icon" aria-hidden="true">✓</div>
				<h4 class="quick-done-title">کاربر جدید با موفقیت ساخته شد</h4>
				<p class="quick-done-note"><span class="quick-done-tag">توجه</span><span class="quick-done-note-text">برای اتصال بهتر آیپی تمیز در کاربر قرار دهید</span><span class="quick-done-tag">توجه</span></p>
				<p class="quick-done-meta">نام کاربری: <b dir="ltr">${esc(username)}</b> · ${fa(count)} لوکیشن</p>
				<div class="quick-done-actions">
					<button class="ds-btn is-primary" id="quick-goto-ips">${icon("globe")}<span>ورود به بخش آیپی تمیز</span></button>
					<button class="ds-btn is-ghost" data-close>بستن</button>
				</div>`;
			body.appendChild(done);
			$("#quick-goto-ips", done).addEventListener("click", () => {
				modal.close();
				go("ips");
			});
		}

		/* v3.0.7 — a failure gets the same treatment as a success: the progress fades
		   out and the failure is shown as its own view, not underneath the bar. */
		build().catch((error) => showResult(() => {
			const failed = document.createElement("div");
			failed.className = "quick-done error";
			failed.dir = "rtl";
			failed.innerHTML = `
				<div class="quick-done-icon" aria-hidden="true">!</div>
				<h4 class="quick-done-title">ساخت کاربر انجام نشد</h4>
				<p class="quick-done-hint">${esc(error.message || "خطای نامشخص")}</p>
				<div class="quick-done-actions">
					<button class="ds-btn" id="quick-retry">تلاش دوباره</button>
					<button class="ds-btn is-ghost" data-close>بستن</button>
				</div>`;
			body.appendChild(failed);
			$("#quick-retry", failed).addEventListener("click", () => {
				modal.close();
				quickUserModal();
			});
		}));
	}

	function uuidFallback() {
		const bytes = new Uint8Array(16);
		crypto.getRandomValues(bytes);
		bytes[6] = (bytes[6] & 0x0f) | 0x40;
		bytes[8] = (bytes[8] & 0x3f) | 0x80;
		const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
		return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
	}

	/** One proxy per line → JSON array (multi-location mode). */
	function normalizeProxyField(value) {
		const text = String(value || "").trim();
		if (!text) return null;
		if (text.startsWith("[")) return text;
		const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
		if (lines.length <= 1) return lines[0] || null;
		return JSON.stringify(lines.map((proxy) => ({ proxy, country: null })));
	}

	/* ── links / QR modal ─────────────────────────────────────────────── */
	/* v2.3.12 — QR for the links modal: the same qrcode-generator global the
	   status page uses (the QR script is inlined in panel.html as well), the same
	   .qr-box look and the same fixed-size SVG that v2.3.11 taught it to paint.
	   Toggle behaviour mirrors the status page: the same button collapses. */
	function renderQrTo(area, text) {
		area.innerHTML = "";
		const qrLib = (typeof qrcode === "function" ? qrcode : (typeof window !== "undefined" && typeof window.qrcode === "function" ? window.qrcode : null));
		if (!qrLib) {
			area.innerHTML = '<div class="ds-banner ds-tone-warning is-inline">کتابخانه QR در دسترس نیست.</div>';
			return;
		}
		try {
			let qr;
			try {
				qr = qrLib(0, "M");
				if (qrLib.stringToBytesFuncs && qrLib.stringToBytesFuncs["UTF-8"]) {
					const prev = qrLib.stringToBytes;
					qrLib.stringToBytes = qrLib.stringToBytesFuncs["UTF-8"];
					qr.addData(text);
					qrLib.stringToBytes = prev;
				} else qr.addData(text);
				qr.make();
			} catch {
				qr = qrLib(0, "L");
				qr.addData(text); qr.make();
			}
			const box = document.createElement("div");
			box.className = "qr-box";
			box.innerHTML = qr.createSvgTag({ cellSize: 5, margin: 2, scalable: true });
			area.appendChild(box);
			const cap = document.createElement("div");
			cap.className = "qr-caption";
			cap.textContent = text.length > 90 ? text.slice(0, 90) + "…" : text;
			area.appendChild(cap);
		} catch (error) {
			area.innerHTML = `<div class="ds-banner ds-tone-danger is-inline">${esc(error.message)}</div>`;
		}
	}

	/* v3.1.2 — the QR code gets its own window with a darker backdrop, so a phone
	   camera sees only the code and nothing else from the links dialog. */
	function openQrWindow(text) {
		const modal = openModal({
			title: "کد QR",
			size: "sm",
			center: true,
			dim: true,
			body: '<div class="qr-window" id="qr-window-area"></div>',
		});
		renderQrTo($("#qr-window-area", modal.root), text);
	}

	async function linksModal(username) {
		let data;
		try {
			data = await api.get(`/api/users/${encodeURIComponent(username)}/links`);
		} catch (error) {
			return toast(error.message, "err");
		}
		const rows = data.links
			.map((link, index) => {
				const remark = decodeURIComponent((link.split("#")[1] || "").replace(/\+/g, " "));
				return `<div class="link-row"><span class="ds-badge ds-tone-info">${fa(index + 1)}</span><span class="txt" title="${esc(link)}">${esc(remark || link)}</span>
					<button class="ds-btn is-sm is-icon" data-copy="${esc(link)}" aria-label="کپی"><svg class="ico" aria-hidden="true"><use href="#i-copy"/></svg></button>
					</div>`;
			})
			.join("");

		const modal = openModal({
			title: `لینک‌های ${esc(username)}`,
			body: `
				<div class="section-title mt-0">اشتراک‌ها</div>
				<div class="ds-card ds-p-3 ds-mb-3">
					<div class="ds-row ds-wrap ds-mb-2">
						<span class="ds-badge ds-tone-info"><svg class="ico inline" aria-hidden="true"><use href="#i-shield"/></svg> V2RayNG · Hiddify · PattN</span>
						<span class="dim ds-caption">فهرست لینک‌ها (Base64) — همه‌ی کلاینت‌های V2Ray</span>
						${hintMarkup("همان لینکِ همیشگی: در V2RayNG، Hiddify، PattN، PattNG،\nV2Box و Streisand یک‌جا کار می‌کند و هر کانفیگ\nبه‌صورت یک سرور جداگانه در فهرست کلاینت می‌نشیند\n— بین‌شان جابه‌جا شدن آسان است.")}
					</div>
					<div class="link-row"><span class="txt" title="${esc(data.sub_url)}">${esc(data.sub_url)}</span><button class="ds-btn is-sm is-icon" data-copy="${esc(data.sub_url)}" aria-label="کپی"><svg class="ico" aria-hidden="true"><use href="#i-copy"/></svg></button><button class="ds-btn is-sm is-icon" data-qr-btn data-qr-text="${esc(data.sub_url)}" aria-label="QR"><svg class="ico" aria-hidden="true"><use href="#i-qr"/></svg></button></div>
				</div>
				<div class="ds-card ds-p-3 ds-mb-3">
					<div class="ds-row ds-wrap ds-mb-2">
						<span class="ds-badge ds-tone-info"><svg class="ico inline" aria-hidden="true"><use href="#i-package"/></svg> sing-box</span>
