	/* ── boot ─────────────────────────────────────────────────────────── */
	/* Live gfx toggle: the CSS blobs only paint when `body` does *not* have
	   `.no-gfx`. v2.3.8 — the SERVER setting is the single source of truth:
	   the sidebar button persists to /api/settings too, so it can never
	   disagree with the settings switch, and a fresh panel boots with the
	   default (ON) instead of a stale per-browser override. */
	function applyGfx(on) {
		document.body.classList.toggle("no-gfx", !on);
		const btn = document.getElementById("btn-gfx");
		if (btn) btn.setAttribute("aria-pressed", on ? "true" : "false");
	}

	function applySidebar(collapsed) {
		const app = document.querySelector(".app");
		const sidebar = document.getElementById("sidebar");
		if (app) app.classList.toggle("collapsed-sidebar", collapsed);
		if (sidebar) sidebar.classList.toggle("collapsed", collapsed);
		try { localStorage.setItem("devcop-sidebar-collapsed", collapsed ? "1" : "0"); } catch {}
		const btn = document.getElementById("btn-sidebar-toggle");
		if (btn) {
			btn.setAttribute("aria-label", collapsed ? "باز کردن منو" : "جمع کردن منو");
			btn.setAttribute("title", collapsed ? "باز کردن منو" : "جمع کردن منو");
			btn.setAttribute("aria-expanded", String(!collapsed));
		}
	}

	/* ── phone drawer (≤640px) ───────────────────────────────────────────
	   On phones the menu is a right-side drawer that starts CLOSED and is
	   driven by body.nav-open (scrim + slide + handle flip, all in CSS).
	   The desktop collapse state above (collapsed-sidebar + localStorage) is
	   a separate concern and stays untouched: one handle, two behaviours,
	   chosen by the media query at click time. */
	const phoneNavQuery = window.matchMedia("(max-width: 640px)");
	function navDrawerOpen() {
		return document.body.classList.contains("nav-open");
	}
	let drawerRestore = null;
	/* v3.1.1 — the drawer's close handle lives in the app bar, which is inside
	   <main>. <main> has to be inert while the drawer is open (it is the page
	   behind the drawer), and that also made the handle unfocusable and left it
	   hidden under the drawer. While the drawer is open the handle therefore
	   moves to the shell (a sibling of <main>) and sits on the drawer's edge;
	   it goes back to the app bar when the drawer closes. */
	const navHandleHome = { parent: null, next: null };
	function placeNavHandle(open) {
		const btn = document.getElementById("btn-sidebar-toggle");
		const shell = document.querySelector(".shell.app");
		const main = $(".main");
		if (!btn || !shell || !main) return;
		if (open && phoneNavQuery.matches) {
			if (btn.parentElement !== shell) {
				navHandleHome.parent = btn.parentElement;
				navHandleHome.next = btn.nextElementSibling;
				shell.insertBefore(btn, main);
			}
			btn.classList.add("sidebar-handle");
			return;
		}
		btn.classList.remove("sidebar-handle");
		if (navHandleHome.parent && btn.parentElement === shell) {
			const anchor = navHandleHome.next && navHandleHome.next.parentElement === navHandleHome.parent ? navHandleHome.next : navHandleHome.parent.firstElementChild;
			navHandleHome.parent.insertBefore(btn, anchor);
		}
	}
	function setNavDrawer(open) {
		const wasOpen = navDrawerOpen();
		if (open && !wasOpen) drawerRestore = document.activeElement;
		document.body.classList.toggle("nav-open", open);
		const sidebar = document.getElementById("sidebar");
		if (sidebar) { sidebar.inert = phoneNavQuery.matches && !open; sidebar.setAttribute("aria-hidden", String(phoneNavQuery.matches && !open)); }
		const main = $(".main"); if (main) main.inert = phoneNavQuery.matches && open;
		placeNavHandle(open);
		const btn = document.getElementById("btn-sidebar-toggle");
		if (btn) {
			btn.setAttribute("aria-label", open ? "بستن منو" : "باز کردن منو");
			btn.setAttribute("title", open ? "بستن منو" : "باز کردن منو");
			btn.setAttribute("aria-expanded", String(open));
		}
		if (open) sidebar?.querySelector('[aria-current="page"]')?.focus({ preventScroll: true });
		else if (wasOpen) (drawerRestore?.isConnected ? drawerRestore : btn)?.focus({ preventScroll: true });
	}

	function registerServiceWorker() {
		if (!("serviceWorker" in navigator)) return;
		// Inside an iframe (preview environments) a service worker adds caching
		// risk and no benefit — PWA installability only matters in a real tab.
		// Any worker left over from an earlier revision is removed together with
		// its cached pages, so a stale login page can never be replayed over an
		// authenticated session.
		const embedded = (() => {
			try {
				return window.self !== window.top;
			} catch {
				return true;
			}
		})();
		if (embedded) {
			try {
				navigator.serviceWorker
					.getRegistrations()
					.then((registrations) => registrations.forEach((registration) => registration.unregister()))
					.catch(() => {});
			} catch {}
			try {
				if (window.caches) window.caches.keys().then((keys) => keys.forEach((key) => window.caches.delete(key))).catch(() => {});
			} catch {}
			return;
		}
		navigator.serviceWorker.register("/sw.js").catch(() => {});
	}

	async function init() {
		/* v2.3.8 — gfx follows the server setting (default ON); the old
		   per-browser localStorage override could leave the sidebar button
		   and the settings switch disagreeing with each other forever. */
		applyGfx(Boolean(boot.gfx));
		try {
			const collapsed = localStorage.getItem("devcop-sidebar-collapsed") === "1";
			applySidebar(collapsed);
		} catch {}
		/* Phone drawer: closed on every load regardless of the desktop
		   collapse preference, so the handle's label matches what is painted. */
		setNavDrawer(false);
		if (!phoneNavQuery.matches) applySidebar(document.querySelector(".app")?.classList.contains("collapsed-sidebar"));
		phoneNavQuery.addEventListener("change", (event) => {
			/* Rotating/resizing out of the phone range must not leave the
			   drawer state stuck on a layout it does not apply to. */
			setNavDrawer(false);
			if (!event.matches) applySidebar(document.querySelector(".app")?.classList.contains("collapsed-sidebar"));
		});
		$$(".ds-drawer-item").forEach((item) => item.addEventListener("click", () => {
			go(item.dataset.page);
			if (navDrawerOpen()) { setNavDrawer(false); $("#page-title").focus({ preventScroll: true }); }
		}));
		$("#btn-logout").addEventListener("click", async () => {
			try {
				await api.post("/api/logout");
			} catch {}
			location.href = "/login";
		});
